S.staffScheduleByBranch=S.staffScheduleByBranch||branches.map(()=>({})); S.nextTurnOverride=S.nextTurnOverride||{}; while(S.staffScheduleByBranch.length<branches.length)S.staffScheduleByBranch.push({}); S.shopSupplies=S.shopSupplies||[]; S.staffProfiles=S.staffProfiles||{}; S.activityLog=S.activityLog||[]; S.reportActivityDate=S.reportActivityDate||today(); S.liveActivitySeenAt=S.liveActivitySeenAt||0; S.sidebarCollapsed=!!S.sidebarCollapsed; S.deepTissue=S.deepTissue||false; S.roomsByBranch=S.roomsByBranch||branches.map(()=>[1,2,3,4,5].map(n=>({n,enabled:true}))); while(S.roomsByBranch.length<branches.length)S.roomsByBranch.push([1,2,3,4,5].map(n=>({n,enabled:true}))); S.roomsByBranch.forEach(a=>{if(!a.some(x=>+x.n===5))a.push({n:5,enabled:true})}); S.supplyFilterBranch=S.supplyFilterBranch??'all'; S.shower=S.shower||false; S.fourHands=S.fourHands||false; S.room=S.room||null; S.manualDebts=S.manualDebts||[]; S.staffPaymentDetails=S.staffPaymentDetails||{}; S.outstandingDate=S.outstandingDate||''; S.outstandingBranch=S.outstandingBranch??'all'; S.branch=S.branch??0; S.pendingBranch=null; S.pinVisible=false; S.soundEnabled=S.soundEnabled!==false; S.receptionPin=S.receptionPin||'2580'; window.bossUnlockedBranch=null; window.receptionUnlockedBranch=null;
const save=()=>{localStorage.setItem('massagePOS4',JSON.stringify(S));try{window.eternityLive?.postMessage({type:'state',state:JSON.parse(JSON.stringify(S))})}catch(e){}};
try{window.eternityLive=new BroadcastChannel('eternity-massage-pos-live');window.eternityLive.onmessage=e=>{if(e.data?.type!=='state'||!e.data.state)return;let before=S.sales?.length||0;Object.assign(S,e.data.state);if(!S.staffScheduleByBranch)S.staffScheduleByBranch=branches.map(()=>({}));if(!S.staffByBranch)S.staffByBranch=branches.map(()=>[]);if(!S.nextTurnOverride)S.nextTurnOverride={};if((S.sales?.length||0)>before){let x=S.sales[S.sales.length-1];if(x&&x.branch===S.branch){showBookingNotice('Live Treatment',`${x.therapist||'Staff'} is treating ${x.customer||'a customer'} · ${branches[x.branch]?.name||''}`);tone(780,.18);speak(`${x.therapist||'Staff'} is treating ${x.customer||'a customer'}`)}}if(document.querySelector('.app'))render()}}catch(e){}
window.addEventListener('storage',e=>{if(e.key!=='massagePOS4'||!e.newValue)return;try{let incoming=JSON.parse(e.newValue),before=S.sales?.length||0;Object.assign(S,incoming);if((S.sales?.length||0)>before){let x=S.sales[S.sales.length-1];if(x&&x.branch===S.branch){showBookingNotice('Live Treatment',`${x.therapist||'Staff'} is treating ${x.customer||'a customer'} · ${branches[x.branch]?.name||''}`);tone(780,.18);speak(`${x.therapist||'Staff'} is treating ${x.customer||'a customer'}`)}}if(document.querySelector('.app'))render()}catch(err){}});
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const I=n=>`<img class="svgicon" src="assets/icons/${n}.svg" alt="">`;
function speak(t){if(!S.soundEnabled)return;try{speechSynthesis.cancel();let u=new SpeechSynthesisUtterance(t);u.lang='en-AU';u.rate=.95;speechSynthesis.speak(u)}catch(e){}}
function tone(f=480,d=.07){if(!S.soundEnabled)return;try{let A=window.AudioContext||webkitAudioContext,a=new A(),o=a.createOscillator(),g=a.createGain();o.connect(g);g.connect(a.destination);o.frequency.value=f;g.gain.value=.035;o.start();g.gain.exponentialRampToValueAtTime(.001,a.currentTime+d);o.stop(a.currentTime+d)}catch(e){}}
document.addEventListener('click',e=>{if(e.target.closest('button'))tone()});
function toast(t,k=''){let x=document.querySelector('#toast');x.textContent=t;x.className='show '+k;setTimeout(()=>x.className='',2500)}
function modal(h){let m=document.querySelector('#modal');if(!m){m=document.createElement('div');m.id='modal';m.className='modal hidden';document.body.appendChild(m)}m.innerHTML=`<div class="modalbox">${h}</div>`;m.classList.remove('hidden');m.style.display='grid';m.style.pointerEvents='auto';document.documentElement.classList.add('modal-open');document.body.classList.add('modal-open')}
function closeM(){let m=document.querySelector('#modal');if(m){m.classList.add('hidden');m.style.display='none'}document.documentElement.classList.remove('modal-open');document.body.classList.remove('modal-open')}
function closeModal(){closeM()}
function today(){return new Date().toISOString().slice(0,10)}
function fmtTime(d){return new Date(d).toLocaleTimeString('en-AU',{hour:'2-digit',minute:'2-digit',hour12:false})}
function money(n){return '$'+Number(n||0).toFixed(2)}
function logActivity(kind,title,detail='',branch=S.branch,meta={}){S.activityLog=S.activityLog||[];S.activityLog.push({id:Date.now()+Math.random(),at:new Date().toISOString(),date:today(),branch,kind,title,detail,meta});if(S.activityLog.length>5000)S.activityLog=S.activityLog.slice(-5000);save()}
function activityIcon(k){return k==='booking'?'calendar':k==='cancel'?'close':k==='payment'?'cash':k==='outstanding'?'clock':k==='supply'?'bell':k==='complete'?'check':'receipt'}

function login(){document.querySelector('#app').innerHTML=`<div class="login-full"><div class="login-card"><div class="brand"><img src="assets/decorations/lotus_logo.svg"><h1>ETERNITY</h1><p>THAI MASSAGE</p><small>Relax · Rebalance · Rejuvenate</small></div><h2>Select Branch</h2><span class="sub">Enter your branch PIN to continue</span><div class="branches">${branches.map((b,i)=>`<button class="branch" onclick="pinModal(${i})"><img class="branchphoto" src="assets/branches/${b.img}"><span><b>${b.name}</b><small>${b.address}<br>${b.phone}</small></span><span class="arrow">›</span></button>`).join('')}</div></div></div>`}
function pinModal(i){S.pendingBranch=i;S.pinVisible=false;modal(`<button class="close" onclick="closeM()">×</button><div class="pinbrand"><img src="assets/decorations/lotus_logo.svg"><h2>Enter PIN</h2><span>${esc(branches[i].name)}</span></div><div class="pinwrap"><input id="branchPin" type="password" class="pin-display" readonly maxlength="4" placeholder="••••"><button class="eye" onclick="togglePin()">${I('eye')}</button></div><div id="pinError" class="pin-error hidden">Incorrect PIN. Please try again.</div><div class="keypad pinpad premium-pinpad">${['1','2','3','4','5','6','7','8','9'].map(k=>`<button onclick="pinKey('${k}')"><span>${k}</span></button>`).join('')}<button class="pin-blank" disabled></button><button onclick="pinKey('0')"><span>0</span></button><button class="pin-back" onclick="pinKey('back')" aria-label="Delete">${I('back')}</button></div><button class="primary fullbtn pin-continue" onclick="enterBranch()">${I('lock')} Continue</button>`)}
function togglePin(){S.pinVisible=!S.pinVisible;branchPin.type=S.pinVisible?'text':'password';document.querySelector('.eye').innerHTML=I(S.pinVisible?'eye_off':'eye')}
function pinKey(k){let e=branchPin,er=document.querySelector('#pinError');if(er)er.classList.add('hidden');if(k==='back'){e.value=e.value.slice(0,-1);return}if(e.value.length<4)e.value+=k;if(e.value.length===4){let i=S.pendingBranch;if(e.value===S.branchPins[i])setTimeout(enterBranch,120);else{tone(180,.2);if(er)er.classList.remove('hidden');setTimeout(()=>{e.value=''},350)}}}
function enterBranch(){let i=S.pendingBranch;if(branchPin.value!==S.branchPins[i]){tone(180,.2);let e=document.querySelector('#pinError');if(e)e.classList.remove('hidden');branchPin.value='';return toast('Incorrect PIN','danger')}S.branch=i;S.page='sales';window.bossUnlockedBranch=null;save();closeM();render();speak('Login successful')}
function updateLiveClock(){let d=new Date(),a=document.querySelector('#liveDate'),t=document.querySelector('#liveTime');if(a)a.textContent=d.toLocaleDateString('en-AU',{weekday:'short',day:'2-digit',month:'short',year:'numeric'});if(t)t.textContent=d.toLocaleTimeString('en-AU',{hour:'2-digit',minute:'2-digit'})} setInterval(updateLiveClock,30000);
function nav(p){S.page=p;save();render()}
function layout(content){let b=branches[S.branch];let navs=[['home','sales','Services'],['calendar','bookings','Bookings'],['users','customers','Customers'],['user','staff','Staff'],['clock','availability','Staff Availability'],['bar_chart','reports','Reports'],['settings','settings','Settings']];return `<div class="app ${S.sidebarCollapsed?'nav-collapsed':''}"><nav class="side"><button class="nav-toggle" onclick="S.sidebarCollapsed=!S.sidebarCollapsed;save();render()" aria-label="${S.sidebarCollapsed?'Open menu':'Close menu'}" title="${S.sidebarCollapsed?'Open menu':'Close menu'}"><span class="toggle-lines"><i></i><i></i><i></i></span><span>${S.sidebarCollapsed?'Open':'Close'}</span></button>${navs.map(x=>`<button class="${S.page===x[1]?'active':''}" onclick="nav('${x[1]}')">${I(x[0])}<span>${x[2]}</span></button>`).join('')}</nav><main class="main page-${S.page}"><div class="top"><div><h1>${esc(b.name)}</h1><div class="sub">${esc(b.address)} · ${esc(b.phone)}</div></div><div class="top-right"><div class="live-clock">${I('clock')}<span><b id="liveDate">${new Date().toLocaleDateString('en-AU',{weekday:'short',day:'2-digit',month:'short',year:'numeric'})}</b><small id="liveTime">${new Date().toLocaleTimeString('en-AU',{hour:'2-digit',minute:'2-digit'})}</small></span></div><button class="pill" onclick="login()">${I('lock')} Switch Branch</button></div></div>${content}</main></div>`}
function staffAvailabilityAllBranches(){
  let now=new Date(),d=today(),fmt=v=>{let x=new Date(v);return isNaN(+x)?'—':x.toLocaleTimeString('en-AU',{hour:'2-digit',minute:'2-digit'})},minsUntil=v=>Math.max(0,Math.ceil((+new Date(v)-Date.now())/60000));
  return `<div class="availability-main-page"><div class="availability-main-head"><div><h2>${I('clock')} Staff Availability</h2><span class="sub">All branches · live treatments and upcoming bookings for ${now.toLocaleDateString('en-AU',{weekday:'long',day:'2-digit',month:'short'})}</span></div><div class="availability-live-pill"><i></i> LIVE</div></div>
  <div class="availability-branch-list">${branches.map((br,bi)=>{let roster=rosterForDate(bi,d),sales=S.sales.filter(x=>x.branch===bi&&x.serviceDate===d),active=sales.filter(x=>+new Date(x.startAt)<=Date.now()&&+new Date(x.endAt)>Date.now()),books=S.bookings.filter(b=>b.branch===bi&&b.date===d&&b.status!=='Cancelled'&&!b.paid);
  return `<section class="availability-branch-card"><div class="availability-branch-head"><div>${I('home')}<span><b>${esc(br.name)}</b><small>${roster.length} staff today · ${active.length} in treatment</small></span></div><strong>${active.length?'ACTIVE':'OPEN'}</strong></div>
  <div class="availability-branch-staff">${roster.map((st,i)=>{let current=active.find(a=>a.therapist===st.name||a.therapist2===st.name),futureSale=sales.filter(a=>(a.therapist===st.name||a.therapist2===st.name)&&+new Date(a.startAt)>Date.now()).sort((a,b)=>+new Date(a.startAt)-+new Date(b.startAt))[0],futureBook=books.filter(b=>b.therapist===st.name&&b.time).map(b=>({...b,_at:new Date(`${d}T${b.time}`)})).filter(b=>+b._at>Date.now()).sort((a,b)=>+a._at-+b._at)[0];
  let nextAt=null,nextEnd=null,nextLabel='';if(futureSale){nextAt=new Date(futureSale.startAt);nextEnd=new Date(futureSale.endAt);nextLabel='Treatment'}if(futureBook&&(!nextAt||+futureBook._at<+nextAt)){nextAt=futureBook._at;let bm=parseInt(futureBook.service)||60;nextEnd=new Date(+nextAt+bm*60000);nextLabel='Booking'}
  let items=sales.filter(a=>a.therapist===st.name||a.therapist2===st.name),countdown=nextAt?minsUntil(nextAt):null;
  return `<div class="availability-row ${current?'busy':'free'}"><div class="availability-row-avatar">${esc(st.name).charAt(0).toUpperCase()}</div><div class="availability-row-name"><small>TURN ${i+1}</small><b>${esc(st.name)}</b><span>${items.length} treatment${items.length===1?'':'s'} today</span></div>
  <div class="availability-row-time">${current?`${I('clock')}<span><small>IN TREATMENT</small><b>${fmt(current.startAt)} – ${fmt(current.endAt)}</b>${current.room?`<em>Room ${current.room}</em>`:''}${nextAt?`<em class="next-booking-note">${nextLabel} ${fmt(nextAt)} · ${countdown} min after current schedule</em>`:''}</span>`:`${I('check')}<span><small>AVAILABLE NOW</small><b>${nextAt?`Free for ${countdown} min`:'No upcoming booking'}</b>${nextAt?`<em class="next-booking-note">${nextLabel}: ${fmt(nextAt)} – ${fmt(nextEnd)}</em>`:'<em>Ready for booking</em>'}</span>`}</div><div class="availability-row-status">${current?'BUSY':'FREE'}</div></div>`}).join('')||`<div class="availability-no-staff">${I('users')}<span><b>No staff added today</b><small>Add staff in this branch to show availability.</small></span></div>`}</div></section>`}).join('')}</div></div>`
}

function render(){let f={sales,bookings,customers,staff,availability:()=>window.receptionUnlockedBranch===S.branch?staffAvailabilityAllBranches():availabilityLock(),reports:()=>window.bossUnlockedBranch===S.branch?reports():reportLock(),settings:()=>window.bossUnlockedBranch===S.branch?settings():settingsLock()};document.querySelector('#app').innerHTML=layout(f[S.page]())}
function total(){let base=S.cart.reduce((a,x)=>a+x.price*x.qty,0);return base+(S.shower?10:0)+(S.deepTissue?10:0)+(S.fourHands?base:0)}
function activeTreatments(){let now=Date.now();return S.sales.filter(x=>x.branch===S.branch&&+new Date(x.startAt)<=now&&+new Date(x.endAt)>now)}
function minsLeft(x){return Math.max(0,Math.ceil((+new Date(x.endAt)-Date.now())/60000))}
function roomStatusBoard(){let active=activeTreatments(),rooms=(S.roomsByBranch[S.branch]||[]).filter(r=>r.enabled);return `<div class="ops-board"><div class="ops-board-head"><div>${I('home')}<span><b>Room Status</b><small>Live availability</small></span></div><em>${active.length} in treatment</em></div><div class="room-status-grid">${rooms.map(r=>{let x=active.find(a=>a.room===r.n);return `<div class="room-status ${x?'occupied':'available'}"><span class="room-dot"></span><div><b>Room ${r.n}</b><small>${x?`${minsLeft(x)} min left · ${esc(x.therapist||'Staff')}`:'Available'}</small></div>${x?`<strong>${minsLeft(x)}m</strong>`:`<strong>FREE</strong>`}</div>`}).join('')}</div></div>`}
function staffAvailabilityBoard(){let d=today(),roster=S.staff.filter(x=>(x.date||d)===d),names=[...new Set(roster.map(x=>typeof x==='string'?x:x.name).filter(Boolean))],active=activeTreatments(),todaySales=S.sales.filter(x=>x.branch===S.branch&&x.serviceDate===d),assigned=todaySales.flatMap(x=>[x.therapist,x.therapist2].filter(Boolean)),last=assigned.filter(n=>names.includes(n)).pop(),ni=last?((names.indexOf(last)+1)%Math.max(names.length,1)):0,next=names[ni]||'';return `<div class="staff-availability-board"><div class="ops-board-head"><div>${I('users')}<span><b>Staff Availability</b><small>${names.length} staff today · Next turn: ${esc(next||'—')}</small></span></div></div><div class="staff-live-grid">${names.map((n,i)=>{let x=active.find(a=>a.therapist===n||a.therapist2===n),isNext=!x&&n===next;return `<div class="staff-live ${x?'busy':isNext?'next':'free'}"><div class="staff-live-avatar">${esc(n).charAt(0).toUpperCase()}</div><span><b>${esc(n)}</b><small>${x?`In Treatment · ${minsLeft(x)} min left`:isNext?'Available · Next Turn':'Available'}</small></span><em>${x?'BUSY':isNext?'NEXT':'FREE'}</em></div>`}).join('')||'<div class="staff-live-empty">Add today’s staff to see live availability.</div>'}</div></div>`}
function sales(){return `<div class="sales-grid"><section class="panel"><div class="section-title">${I('home')}<div><h2>Massage Services</h2><span>Select a treatment duration</span></div></div><div class="services">${S.prices.map((s,i)=>`<button class="service ${S.cart.length?(S.cart[0].name===`${s.m} minutes`?'service-selected':'service-disabled'):''}" ${S.cart.length&&S.cart[0].name!==`${s.m} minutes`?'disabled':''} onclick="add(${i})"><img src="assets/service${s.m}.jpg"><div><span>${s.m} minutes</span><strong>${money(s.p)}</strong></div></button>`).join('')}</div><button class="shower-addon ${S.shower?'active':''}" onclick="S.shower=!S.shower;save();render()">${I('plus')}<span><b>Shower Room</b><small>Optional add-on</small></span><strong>+$10</strong></button><button class="shower-addon deep-tissue ${S.deepTissue?'active':''}" onclick="S.deepTissue=!S.deepTissue;save();render()">${I('plus')}<span><b>Deep Tissue Massage</b><small>Optional treatment add-on</small></span><strong>+$10</strong></button><button class="shower-addon fourhands ${S.fourHands?'active':''}" onclick="S.fourHands=!S.fourHands;save();render()">${I('users')}<span><b>Couple Massage</b><small>1–2 customers · exactly 2 therapists</small></span><strong>${S.fourHands?'ON':'ADD'}</strong></button><div class="room-picker"><b>Room</b><span>Select before payment</span><div class="room-buttons">${(S.roomsByBranch[S.branch]||[]).filter(o=>o.enabled).map(o=>{let r=o.n,busy=roomBusy(r);return `<button class="${S.room===r?'selected':''} ${busy&&S.room!==r?'busy':''}" ${busy&&S.room!==r?'disabled':''} onclick="S.room=${r};save();render()">Room ${r}${busy?' · Busy':''}</button>`}).join('')}</div></div></section><aside class="cart"><h3>${I('receipt')} Current Order</h3>${S.cart.length?S.cart.map((x,i)=>`<div class="cart-item"><div><b>${x.name}</b><small>${money(x.price)}</small></div><div class="qty"><button onclick="qty(${i},-1)">−</button><b>${x.qty}</b><button onclick="qty(${i},1)">+</button></div><button class="iconbtn danger" onclick="del(${i})">${I('trash')}</button></div>`).join(''):`<div class="empty">${I('receipt')}<b>No services selected</b></div>`}<div class="checkout-stack"><div class="total"><span>Total</span><b>${money(total())}</b></div><div class="payrow"><button class="cash" onclick="paymentModal('Cash')">${I('cash')} Cash</button><button class="card" onclick="paymentModal('Card')">${I('card')} Card</button></div></div><button class="clearorder checkout-trash" onclick="clearCart()">${I('trash')} Clear Order</button></aside></div>`}
function add(i){let s=S.prices[i],n=`${s.m} minutes`;if(S.cart.length&&S.cart[0].name===n){if(+s.m===60&&S.cart[0].qty===1){S.cart[0].qty=2;save();render();toast('2 hours selected');return}S.cart=[];S.shower=false;S.fourHands=false;S.deepTissue=false;S.room=null;save();render();return}if(S.cart.length)return toast('Tap the selected service again to deselect it first.');S.cart=[{name:n,price:s.p,qty:1}];save();render()}
function qty(i,n){let x=S.cart[i];if(n>0){if(parseInt(x.name)===60&&x.qty<2){x.qty++;save();render();return}return toast('Only 60 minutes can be doubled to 2 hours.')}x.qty+=n;if(x.qty<1)S.cart.splice(i,1);save();render()} function del(i){S.cart.splice(i,1);save();render()} function clearCart(){S.cart=[];S.shower=false;S.fourHands=false;S.deepTissue=false;S.room=null;save();render();toast('Order cleared')}
function bookingOptions(){return S.bookings.filter(b=>b.branch===S.branch&&!b.paid).map(b=>`<option value="${b.id}">${esc(b.name||'Booking')} · ${b.date} ${b.time} · ${esc(b.service)}</option>`).join('')}
function quickAmounts(t){let vals=[...new Set([...S.prices.map(x=>x.p),50,100,200,300,500,1000,Math.ceil(t)])].filter(x=>x>=t||S.prices.some(p=>p.p===x)).sort((a,b)=>a-b);return vals.map(v=>`<button onclick="setCash(${v})">${v===Math.ceil(t)&&v===t?'Exact ':''}$${v}</button>`).join('')}
function roomBusy(r){let now=Date.now();return S.sales.some(x=>x.branch===S.branch&&x.room===r&&+new Date(x.startAt)<=now&&+new Date(x.endAt)>now)}
function openCashKeypad(){
  let input=document.querySelector('#cashIn');
  if(!input)return toast('Cash amount field is not available','danger');
  document.querySelector('#cashKeypadOverlay')?.remove();
  window.cashPadTemp=input.value||'';
  let ov=document.createElement('div');
  ov.id='cashKeypadOverlay';
  ov.className='cash-keypad-overlay cash-keypad-body-overlay';
  ov.innerHTML=`<div class="cash-keypad-card" role="dialog" aria-modal="true">
    <button type="button" class="cash-pad-close" onclick="closeCashKeypad()" aria-label="Close">×</button>
    <div class="cash-pad-head"><span>${I('cash')}</span><div><h2>Amount Received</h2><small>Enter cash amount</small></div></div>
    <div id="cashPadValue" class="cash-pad-value">${esc(window.cashPadTemp||'0')}</div>
    <div class="cash-pad-quick">
      <button type="button" onclick="cashPadAdd(20)">$20</button>
      <button type="button" onclick="cashPadAdd(50)">$50</button>
      <button type="button" onclick="cashPadAdd(100)">$100</button>
      <button type="button" onclick="cashPadExact()">Exact</button>
    </div>
    <div class="cash-pad">
      ${[1,2,3,4,5,6,7,8,9].map(n=>`<button type="button" onclick="cashPadKey('${n}')">${n}</button>`).join('')}
      <button type="button" onclick="cashPadBack()">⌫</button>
      <button type="button" onclick="cashPadKey('0')">0</button>
      <button type="button" class="cash-pad-clear" onclick="cashPadClear()">${I('trash')}</button>
    </div>
    <button type="button" class="primary fullbtn cash-pad-done" onclick="applyCashPad()">Done</button>
  </div>`;
  document.body.appendChild(ov);
}
function closeCashKeypad(){document.querySelector('#cashKeypadOverlay')?.remove()}
function updateCashPadDisplay(){let v=document.querySelector('#cashPadValue');if(v)v.textContent=window.cashPadTemp||'0'}
function cashPadKey(n){window.cashPadTemp=(window.cashPadTemp||'')+String(n);updateCashPadDisplay()}
function cashPadBack(){window.cashPadTemp=(window.cashPadTemp||'').slice(0,-1);updateCashPadDisplay()}
function cashPadClear(){window.cashPadTemp='';updateCashPadDisplay()}
function cashPadAdd(n){window.cashPadTemp=String((Number(window.cashPadTemp||0)+Number(n)));updateCashPadDisplay()}
function cashPadExact(){window.cashPadTemp=String(Number(total()).toFixed(2).replace(/\.00$/,''));updateCashPadDisplay()}
function applyCashPad(){let x=document.querySelector('#cashIn');if(x){x.value=window.cashPadTemp||'';calcChange()}closeCashKeypad()}

function rosterForDate(bi,date){
  let manual=(S.staffByBranch[bi]||[]).filter(x=>(x.date||date)===date).map(x=>typeof x==='string'?{name:x,date}:x).filter(x=>x&&x.name);
  let planned=((S.staffScheduleByBranch[bi]||{})[date]||[]).map((x,i)=>typeof x==='string'?{name:x,date,order:i+1,source:'boss'}:{...x,date,source:x.source||'boss'});
  let all=[...planned,...manual], seen=new Set(), out=[];
  all.sort((a,b)=>(+a.order||999)-(+b.order||999));
  for(let x of all){let k=String(x.name).trim().toLowerCase();if(k&&!seen.has(k)){seen.add(k);out.push({...x,order:out.length+1})}}
  return out;
}
function syncRosterDate(bi,date){
  let merged=rosterForDate(bi,date);
  let keep=(S.staffByBranch[bi]||[]).filter(x=>(x.date||date)!==date);
  S.staffByBranch[bi]=keep.concat(merged.map((x,i)=>({...x,date,order:i+1})));
}
function todaysStaff(){let d=today();syncRosterDate(S.branch,d);return (S.staffByBranch[S.branch]||[]).filter(x=>(x.date||d)===d).sort((a,b)=>(+a.order||999)-(+b.order||999)).map(x=>typeof x==='string'?{name:x,date:d}:x).filter(x=>x&&x.name)}

function nextTurnStaffName(){
  let names=todaysStaff().map(x=>x.name).filter(Boolean);
  if(!names.length)return '';
  let ov=S.nextTurnOverride?.[S.branch]?.[today()];
  if(ov&&names.includes(ov))return ov;
  let events=[
    ...S.bookings.filter(b=>b.branch===S.branch&&b.date===today()&&b.status!=='Cancelled'&&b.therapist&&b.therapist!=='Any available').map(b=>({at:`${b.date}T${b.time||'00:00'}`,assigned:[b.therapist]})),
    ...S.sales.filter(x=>x.branch===S.branch&&x.serviceDate===today()).map(x=>({at:x.startAt,assigned:[x.therapist,x.therapist2].filter(Boolean)}))
  ].sort((a,b)=>+new Date(a.at)-+new Date(b.at));
  let used=new Set();
  for(let x of events){
    let assigned=x.assigned.filter(n=>names.includes(n));
    for(let n of assigned){if(!used.has(n))used.add(n);if(used.size===names.length)used.clear()}
  }
  return names.find(n=>!used.has(n))||names[0];
}
function advanceNextTurn(){
  let names=todaysStaff().map(x=>x.name);if(!names.length)return;
  let cur=nextTurnStaffName(),i=names.indexOf(cur);let next=names[(i+1)%names.length];
  S.nextTurnOverride[S.branch]=S.nextTurnOverride[S.branch]||{};S.nextTurnOverride[S.branch][today()]=next;save();render();tone(700,.12);toast(`Next Turn changed to ${next}`,'success');
}

function paymentModal(method,bookingId=''){if(!S.cart.length&&!bookingId)return toast('Please select a service');if(bookingId)loadBookingCart(bookingId);let t=total();modal(`<button class="close" onclick="closeM()">×</button><div class="modal-title"><div><h2>${method} Payment</h2><span>Complete customer and therapist details</span></div></div><div class="field payment-type-field"><label>${I('user')} Type</label><select id="payTypeSelect" onchange="setType(this.value)"><option value="Walk-in">Walk-in</option><option value="Booking">Booking</option><option value="Request">Request</option></select></div><div id="bookingField" class="field hidden"><label>${I('calendar')} Select Booking</label><select id="payBooking" onchange="fillBooking()"><option value="">Choose booking</option>${bookingOptions()}</select></div><div class="formgrid"><div class="field"><label>${I('user')} Customer Name${S.fourHands?' 1':''}</label><input id="payName" placeholder="Optional"></div>${S.fourHands?`<div class="field"><label>${I('user')} Customer Name 2 <span class="optional-label">(Optional)</span></label><input id="payName2" placeholder="Optional second customer"></div>`:''}<div class="field"><label>${I('users')} Therapist 1</label><select id="payTherapist"><option value="">Select therapist</option>${todaysStaff().map(x=>`<option value="${esc(x.name)}" ${x.name===nextTurnStaffName()?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div>${S.fourHands?`<div class="field"><label>${I('users')} Therapist 2 · Couple</label><select id="payTherapist2"><option value="">Select second therapist</option>${todaysStaff().map(x=>`<option>${esc(x.name)}</option>`).join('')}</select></div>`:''}<div class="field"><label>${I('clock')} Treatment Start Time</label><input id="payStartTime" type="time" value="${new Date().toTimeString().slice(0,5)}"><small>Current time is selected automatically. Staff can adjust it before payment.</small></div><div class="field"><label>${I('home')} Room</label><select id="payRoom" onchange="S.room=+this.value||null;save()"><option value="">Select available room</option>${(S.roomsByBranch[S.branch]||[]).filter(o=>o.enabled&&(!roomBusy(o.n)||S.room===o.n)).map(o=>`<option value="${o.n}" ${S.room===o.n?'selected':''}>Room ${o.n}</option>`).join('')}</select><small>Rooms currently in use are hidden until the treatment finishes.</small></div></div><div class="amount">Total Amount <b>${money(t)}</b></div>${method==='Cash'?`<div class="cash-shortcuts"><button onclick="addCash(20)">$20</button><button onclick="addCash(50)">$50</button><button onclick="addCash(100)">$100</button><button class="exact-cash" onclick="setExactCash(${t})">Exact ${money(t)}</button></div><div class="field cash-input-field"><label>Amount Received</label><div class="cash-input-wrap"><input id="cashIn" type="text" inputmode="numeric" autocomplete="off" placeholder="Tap to enter amount" readonly onclick="openCashKeypad();return false" onfocus="openCashKeypad();this.blur()"><button type="button" class="cash-clear" onclick="clearCash()" title="Clear amount">${I('trash')}</button></div></div><div id="chg" class="change">Change $0.00</div>`:`<div class="cardtypes"><span>${I('card')} Card payment</span><small>Process on your card terminal, then confirm.</small></div>`}<button class="primary fullbtn" onclick="confirmPayment('${method}')">Pay ${method}</button>`);window.payType='Walk-in';if(bookingId){setType('Booking');payBooking.value=bookingId;fillBooking()}}
function setType(t){window.payType=t;let sel=document.querySelector('#payTypeSelect');if(sel)sel.value=t;let bf=document.querySelector('#bookingField');if(bf)bf.classList.toggle('hidden',t!=='Booking')}
function loadBookingCart(id){let b=S.bookings.find(x=>x.id==id),m=parseInt(b.service),s=S.prices.find(x=>x.m===m);S.cart=[{name:`${m} minutes`,price:s?.p||0,qty:1}]}
function fillBooking(){let b=S.bookings.find(x=>x.id==payBooking.value);if(!b)return;payName.value=b.name||'';if(b.therapist!=='Any available')payTherapist.value=b.therapist;loadBookingCart(b.id);document.querySelector('.amount b').textContent=money(total())}
function addCash(v){cashIn.value=(+cashIn.value||0)+v;calcChange()} function setExactCash(v){cashIn.value=v;calcChange()} function clearCash(){cashIn.value='';calcChange()} function cashKey(k){cashIn.value=(cashIn.value||'')+k;calcChange()} function backCash(){cashIn.value=cashIn.value.slice(0,-1);calcChange()}
function calcChange(){let c=(+cashIn.value||0)-total();chg.textContent=(c>=0?'Change ':'Short ')+money(Math.abs(c));chg.className='change '+(c<0?'negative':'')}
function confirmPayment(method){S.room=+(document.querySelector('#payRoom')?.value||S.room)||null;let th=payTherapist.value;if(!th)return toast('Please select a therapist');let th2=S.fourHands&&document.querySelector('#payTherapist2')?payTherapist2.value:'';if(S.fourHands&&(!th2||th2===th))return toast('Please select a different second therapist');if(!S.room)return toast('Please select a room');if(roomBusy(S.room))return toast('This room is currently occupied');if(method==='Cash'&&(+cashIn.value||0)<total())return toast('Amount received is not enough');let type=window.payType||'Walk-in',bid=type==='Booking'?payBooking.value:null,b=bid?S.bookings.find(x=>x.id==bid):null;let customer=payName.value.trim()||type,customer2=S.fourHands?(document.querySelector('#payName2')?.value.trim()||''):'';let chosenTime=document.querySelector('#payStartTime')?.value||new Date().toTimeString().slice(0,5),start=b?new Date(`${b.date}T${chosenTime}`):new Date(`${today()}T${chosenTime}`),cursor=new Date(start);let showerPending=S.shower?10:0,deepPending=S.deepTissue?10:0;S.cart.forEach(x=>{for(let q=0;q<x.qty;q++){let mins=parseInt(x.name),end=new Date(cursor.getTime()+mins*60000),base=x.price+showerPending+deepPending,tax=S.tax.enabled?base*S.tax.rate/(100+S.tax.rate):0;S.sales.push({id:Date.now()+Math.random(),branch:S.branch,customer,customer2,type,therapist:th,therapist2:th2||'',fourHands:!!S.fourHands,couple:!!S.fourHands,deepTissue:deepPending>0,room:S.room,minutes:mins,total:base+(S.fourHands?x.price:0),tax,method,shower:showerPending>0,startAt:cursor.toISOString(),endAt:end.toISOString(),serviceDate:(b?b.date:today())});showerPending=0;deepPending=0;cursor=end}});if(b)b.paid=true;logActivity('payment','Customer started treatment',`${customer} · ${method} · ${th} · ${branches[S.branch].name}`,S.branch,{customer,therapist:th,method});if(S.nextTurnOverride[S.branch])delete S.nextTurnOverride[S.branch][today()];S.cart=[];S.shower=false;S.fourHands=false;S.deepTissue=false;S.room=null;save();closeM();render();tone(760,.18);speak(method==='Cash'?'Cash payment successful':'Card payment successful');toast(`${method} payment successful`,'success');if(S.tax.eReceipt)setTimeout(()=>offerReceipt(customer,method),300)}
function offerReceipt(customer,method){window.receiptCountdown=5;window.receiptTimer&&clearInterval(window.receiptTimer);modal(`<button class="close" onclick="closeM()">×</button><div class="modal-title">${I('receipt')}<div><h2>E-Receipt</h2><span>Payment completed for ${esc(customer)}</span></div></div><div class="receipt-preview"><b>${esc(branches[S.branch].name)}</b><span>${new Date().toLocaleString('en-AU')}</span><hr><span>Payment: ${method}</span><span>Tax: ${S.tax.enabled?S.tax.rate+'% enabled':'Not applied'}</span></div><div class="formgrid"><div class="field"><label>${I('mail')} Email</label><input id="receiptEmail" type="email" placeholder="customer@example.com"></div><div class="field"><label>${I('phone')} Mobile</label><input id="receiptPhone" inputmode="tel" placeholder="04xx xxx xxx"></div></div><div class="receipt-actions"><button class="primary" onclick="pauseReceiptTimer();sendReceiptEmail('${esc(customer)}','${method}')">${I('mail')} Send by Email</button><button class="primary smsbtn" onclick="pauseReceiptTimer();sendReceiptSMS('${esc(customer)}','${method}')">${I('phone')} Send by SMS</button></div><div class="receipt-countdown">Closing in <b id="receiptCount">5</b> seconds if no action is selected.</div>`);window.receiptTimer=setInterval(()=>{window.receiptCountdown--;let e=document.querySelector('#receiptCount');if(e)e.textContent=window.receiptCountdown;if(window.receiptCountdown<=0){clearInterval(window.receiptTimer);closeM()}},1000)}
function pauseReceiptTimer(){if(window.receiptTimer){clearInterval(window.receiptTimer);window.receiptTimer=null}let e=document.querySelector('.receipt-countdown');if(e)e.textContent='Auto-close paused while sending receipt.'}
function receiptText(customer,method){let b=branches[S.branch];return `${b.name}%0A${b.address}%0ACustomer: ${customer}%0APayment: ${method}%0AThank you for visiting us.`}
function sendReceiptEmail(customer,method){let e=receiptEmail.value.trim();if(!e)return toast('Enter customer email');let subject=encodeURIComponent(`${branches[S.branch].name} E-Receipt`),body=receiptText(customer,method);window.location.href=`mailto:${encodeURIComponent(e)}?subject=${subject}&body=${body}`;speak('Opening email receipt')}
function sendReceiptSMS(customer,method){let p=receiptPhone.value.replace(/\s/g,'');if(!p)return toast('Enter customer mobile number');openSMS(p,decodeURIComponent(receiptText(customer,method).replace(/%0A/g,'%0A')));speak('Opening message receipt')}
function staffAvailabilityPage(){let staff=todaysStaff(),active=activeTreatments(),next=nextTurnStaffName(),todaySales=S.sales.filter(x=>x.branch===S.branch&&x.serviceDate===today()),completed=todaySales.length;document.querySelector('#staffAvailabilityPage')?.remove();let page=document.createElement('div');page.id='staffAvailabilityPage';page.className='staff-availability-page';page.innerHTML=`<div class="availability-page-shell"><div class="availability-page-top"><div class="availability-page-title"><div class="availability-page-icon">${I('users')}</div><div><span>TODAY'S TEAM</span><h1>Staff Availability</h1><p>${esc(BRANCHES[S.branch].name)} · ${staff.length} staff · ${completed} treatments today</p></div></div><button type="button" class="availability-page-x" onclick="closeStaffAvailability()" aria-label="Close">×</button></div><div class="availability-page-summary"><div class="availability-summary-card available-card">${I('check')}<span><b>${staff.filter(s=>!active.some(a=>a.therapist===s.name||a.therapist2===s.name)).length}</b><small>Available Now</small></span></div><div class="availability-summary-card busy-card">${I('clock')}<span><b>${active.length}</b><small>In Treatment</small></span></div><div class="availability-summary-card next-card">${I('users')}<span><b>${esc(next||'—')}</b><small>Next Turn</small></span></div></div><div class="availability-page-section-head"><div><h2>Today's Staff</h2><p>Live therapist status and treatment details</p></div><span>${new Date().toLocaleTimeString('en-AU',{hour:'2-digit',minute:'2-digit'})}</span></div><div class="availability-page-grid">${staff.map((s,i)=>{let x=active.find(a=>a.therapist===s.name||a.therapist2===s.name),isNext=!x&&s.name===next,items=todaySales.filter(a=>a.therapist===s.name||a.therapist2===s.name),mins=items.reduce((n,a)=>n+(Number(a.mins)||0),0);return `<article class="availability-staff-card ${x?'busy':isNext?'next':'free'}"><div class="availability-staff-top"><div class="availability-big-avatar">${esc(s.name).charAt(0).toUpperCase()}</div><div class="availability-staff-name"><small>TURN ${i+1}</small><h3>${esc(s.name)}</h3><span>${items.length} treatment${items.length===1?'':'s'} · ${mins} min today</span></div><strong>${x?'BUSY':isNext?'NEXT TURN':'AVAILABLE'}</strong></div><div class="availability-staff-detail">${x?`<div class="availability-live-treatment">${I('clock')}<span><b>In Treatment</b><small>${minsLeft(x)} minutes remaining${x.room?` · Room ${x.room}`:''}</small></span></div>`:`<div class="availability-ready">${I('check')}<span><b>${isNext?'Ready for next customer':'Available now'}</b><small>${isNext?'Next therapist in rotation':'Waiting for treatment'}</small></span></div>`}</div>${items.length?`<div class="availability-history"><b>Today</b>${items.slice(-3).reverse().map(a=>`<div><span>${esc(a.customer||a.name||a.type||'Customer')}</span><small>${a.mins||0} min${a.room?` · Room ${a.room}`:''}</small></div>`).join('')}</div>`:''}</article>`}).join('')||`<div class="availability-page-empty">${I('users')}<h3>No staff added today</h3><p>Add staff from Staff Today and they will appear here automatically.</p></div>`}</div></div>`;document.body.appendChild(page);requestAnimationFrame(()=>page.classList.add('show'));document.documentElement.classList.add('availability-open');document.body.classList.add('availability-open')}
