function customerVisitCount(b){let phone=String(b.phone||'').replace(/\D/g,''),name=String(b.name||'').trim().toLowerCase();return S.bookings.filter(x=>x.branch===S.branch&&((phone&&String(x.phone||'').replace(/\D/g,'')===phone)||(!phone&&name&&String(x.name||'').trim().toLowerCase()===name))).length}
function isRegularCustomer(b){return customerVisitCount(b)>=3}
function bookingDisplayStatus(b){if(b.status==='Cancelled')return'Cancelled';if(b.status==='Late')return'Late';if(b.paid){let q=S.sales.filter(x=>x.branch===S.branch&&x.type==='Booking'&&String(x.customer||'').trim().toLowerCase()===String(b.name||'').trim().toLowerCase()&&x.serviceDate===b.date);if(q.length&&q.every(x=>Date.now()>=+new Date(x.endAt)))return'Finished';return'Paid'}return'Booked'}
function bookings(){let d=S.bookingRecordDate||today(),rows=S.bookings.filter(b=>b.branch===S.branch&&b.date>=today()).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)),daily=S.bookings.filter(b=>b.branch===S.branch&&b.date===d);return `<div class="panel"><div class="headrow"><div><h2>${I('calendar')} Bookings</h2><span class="sub">Upcoming appointments, customer records and payment status</span></div><div class="booking-head-actions"><button class="primary" onclick="bookingModal()">${I('plus')} New Booking</button></div></div><div class="booking-records"><div class="headrow compacthead"><div><h3>Customer Records by Day</h3><span class="sub">${new Date(d+`T00:00:00`).toLocaleDateString(`en-AU`,{weekday:`long`,day:`numeric`,month:`long`,year:`numeric`})} · Saved history by selected calendar date</span></div><input class="datepick" type="date" value="${d}" onchange="S.bookingRecordDate=this.value;save();render()"></div><div class="customer-record-scroll">${daily.map((b,ri)=>`<button type="button" class="customer-record-mini" onclick="bookingCustomerDetailByIndex(${ri},'${d}')"><div class="customer-record-person">${I('user')}</div><b>${isRegularCustomer(b)?'<span class="regular-star">★</span> ':''}${esc(b.name||'Booking')}</b><span>›</span></button>`).join('')||'<div class="empty-record">No customer records for this date.</div>'}</div><div id="customerRecordDetail" class="customer-record-detail hidden"></div></div><div class="tablewrap booking-table"><table><tr><th>${I('clock')} Time</th><th>${I('user')} Customer</th><th>${I('phone')} Phone</th><th>Service</th><th>Therapist</th><th>Status</th><th>Action</th></tr>${rows.map(b=>`<tr><td><div class="booking-time-cell">${I('clock')}<span>${b.date}<b>${b.time}</b></span></div></td><td><b class="customer-name">${esc(b.name||'Booking')}</b>${b.notes?`<div class="booking-note-strong">${I('receipt')} ${esc(b.notes)}</div>`:''}</td><td>${b.phone?`<a class="phone-link phone-cell" href="tel:${esc(b.phone)}">${I('phone')} ${esc(b.phone)}</a>`:'<span class="muted">No phone</span>'}</td><td><b>${esc(b.service)}</b><div class="booking-service-addons">${b.shower?'<span class="addon-chip shower">+ Shower</span>':''}${b.deepTissue?'<span class="addon-chip deep">+ Deep</span>':''}${b.couple?'<span class="addon-chip couple">Couple</span>':''}</div></td><td>${esc(b.therapist)}</td><td><span class="badge ${bookingDisplayStatus(b)==='Late'?'late':bookingDisplayStatus(b)==='Cancelled'?'cancelled':bookingDisplayStatus(b)==='Finished'?'finished':b.paid?'done':'upcoming'}">${bookingDisplayStatus(b)}</span></td><td><div class="booking-actions"><button class="mini secondary" onclick="editBookingModal('${b.id}')">${I('edit')} Edit</button><button class="mini late-action" onclick="setBookingStatus('${b.id}','Late')">${I('clock')} Late</button><button class="mini cancel-action" onclick="setBookingStatus('${b.id}','Cancelled')"><svg class="svgicon cancel-svg" viewBox="0 0 24 24" aria-hidden="true"><path d="M6 6l12 12M18 6L6 18" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"/></svg> Cancel</button>${b.paid||b.status==='Cancelled'?'':`<button class="mini pay-action" onclick="S.page='sales';save();render();setTimeout(()=>paymentModal('Cash','${b.id}'),50)">${I('cash')} Pay</button>`}</div></td></tr>`).join('')||'<tr><td colspan="7">No bookings.</td></tr>'}</table></div></div>`}
function setBookingStatus(id,status){let b=S.bookings.find(x=>String(x.id)===String(id));if(!b)return;if(status==='Cancelled')return cancelBookingPin(id);b.status=status;save();render();tone(520,.18);speak('Customer marked late');toast('Booking marked Late','success')}
function cancelBookingPin(id){window.cancelBookingId=id;modal(`<div class="cancel-confirm-center"><button class="close" onclick="closeM()">×</button><div class="cancel-confirm-icon"><svg class="cancel-large-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M6 6l12 12M18 6L6 18" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round"/></svg></div><div class="modal-title"><div><h2>Confirm Cancellation</h2><span>Enter this store PIN to cancel the booking</span></div></div><div class="pinwrap"><input id="cancelPin" type="password" class="pin-display" readonly maxlength="4" placeholder="••••"><button class="eye" onclick="let e=document.querySelector('#cancelPin');e.type=e.type==='password'?'text':'password'">${I('eye')}</button></div><div id="cancelPinError" class="pin-error hidden">Incorrect store PIN.</div><div class="keypad pinpad premium-pinpad">${['1','2','3','4','5','6','7','8','9'].map(k=>`<button onclick="cancelPinKey('${k}')"><span>${k}</span></button>`).join('')}<button class="pin-blank" disabled></button><button onclick="cancelPinKey('0')"><span>0</span></button><button class="pin-back" onclick="cancelPinKey('back')">${I('back')}</button></div></div>`)}
function cancelPinKey(k){let e=document.querySelector('#cancelPin');if(!e)return;if(k==='back')e.value=e.value.slice(0,-1);else if(e.value.length<4)e.value+=k;if(e.value.length===4){if(e.value===S.branchPins[S.branch]){let b=S.bookings.find(x=>String(x.id)===String(window.cancelBookingId));if(b){b.status='Cancelled';logActivity('cancel','Booking cancelled',`${b.name||'Booking'} · ${b.time}`,b.branch,{customer:b.name||'Booking'});save()}closeM();render();tone(260,.25);speak('Booking cancelled');toast('Booking cancelled','success')}else{document.querySelector('#cancelPinError')?.classList.remove('hidden');tone(170,.2);setTimeout(()=>e.value='',350)}}}
function deleteBookingRecord(id){let b=S.bookings.find(x=>String(x.id)===String(id));if(!b)return;if(!confirm('Delete this customer booking record?'))return;S.bookings=S.bookings.filter(x=>String(x.id)!==String(id));save();render();toast('Customer record deleted','success')}
function editBookingModal(id){let b=S.bookings.find(x=>String(x.id)===String(id));if(!b)return;modal(`<button class="close" onclick="closeM()">×</button><div class="modal-title">${I('edit')}<div><h2>Edit Booking</h2><span>Update customer appointment details</span></div></div><div class="formgrid"><div class="field"><label>Customer Name</label><input id="ebn" value="${esc(b.name||'')}"></div><div class="field"><label>Phone</label><input id="ebp" inputmode="tel" value="${esc(b.phone||'')}"></div><div class="field"><label>Date</label><input id="ebd" type="date" value="${b.date}"></div><div class="field"><label>Time</label><input id="ebt" type="time" value="${b.time}"></div><div class="field"><label>Service</label><select id="ebs">${S.prices.map(s=>`<option ${b.service.startsWith(String(s.m))?'selected':''}>${s.m} minutes — ${money(s.p)}</option>`).join('')}</select></div><div class="field"><label>Therapist (Optional)</label><select id="ebth"><option ${b.therapist==='Any available'?'selected':''}>Any available</option>${S.staff.map(x=>`<option ${b.therapist===x.name?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="field fullspan"><label>Notes</label><textarea id="ebnote" rows="3">${esc(b.notes||'')}</textarea></div></div><button class="primary fullbtn" onclick="saveBookingEdit('${b.id}')">${I('check')} Save Changes</button>`)}
function saveBookingEdit(id){let b=S.bookings.find(x=>String(x.id)===String(id));if(!b)return;b.name=ebn.value.trim()||'Booking';b.phone=ebp.value.replace(/[^\d+ ]/g,'');b.date=ebd.value;b.time=ebt.value;b.service=ebs.value;b.therapist=ebth.value;b.notes=ebnote.value.trim();b.alerted=false;b.alerted10=false;b.alerted5=false;save();closeM();render();speak('Booking updated');toast('Booking updated','success')}
function bookingModal(){modal(`<button class="close" onclick="closeM()">×</button><div class="modal-title">${I('calendar')}<div><h2>New Booking</h2></div></div><div class="formgrid"><div class="field"><label>Customer Name</label><input id="bn"></div><div class="field"><label>Phone</label><input id="bp" inputmode="numeric"></div><div class="field"><label>Date</label><input id="bd" type="date" value="${today()}"></div><div class="field"><label>Time</label><input id="bt" type="time"></div><div class="field"><label>Service</label><select id="bs">${S.prices.map(s=>`<option>${s.m} minutes — ${money(s.p)}</option>`).join('')}</select></div><div class="field"><label>Therapist (Optional)</label><select id="bth"><option>Any available</option>${todaysStaff().map(x=>`<option>${esc(x.name)}</option>`).join('')}</select></div><div class="field fullspan"><label>Booking Add-ons</label><div class="booking-addon-grid"><label><input id="bshower" type="checkbox"><span>${I('plus')} Shower Room <b>+$10</b></span></label><label><input id="bdeep" type="checkbox"><span>${I('plus')} Deep Tissue <b>+$10</b></span></label><label><input id="bcouple" type="checkbox"><span>${I('users')} Couple Massage <b>ADD</b></span></label></div></div><div class="field fullspan"><label>Notes</label><textarea id="bnote" rows="3" placeholder="Customer preference, request or other note"></textarea></div></div><button class="primary fullbtn" onclick="saveBooking()">${I('check')} Save Booking</button>`)}
function saveBooking(){if(!bd.value||!bt.value)return toast('Date and time are required');S.bookings.push({id:Date.now(),branch:S.branch,name:bn.value.trim()||'Booking',phone:bp.value.replace(/\D/g,''),date:bd.value,time:bt.value,service:bs.value,therapist:bth.value,notes:bnote.value.trim(),shower:!!document.querySelector('#bshower')?.checked,deepTissue:!!document.querySelector('#bdeep')?.checked,couple:!!document.querySelector('#bcouple')?.checked,paid:false,alerted:false,alerted10:false,alerted5:false});save();closeM();render();tone(720,.18);speak('New booking saved');toast(`New booking saved: ${bn.value.trim()||'Customer'} · ${bt.value}`,'booking');showBookingNotice('New Booking',`${bn.value.trim()||'Customer'} · ${bt.value}`);logActivity('booking','New booking',`${bn.value.trim()||'Customer'} · ${bt.value} · ${bs.value}`,S.branch,{customer:bn.value.trim()||'Customer',time:bt.value})}
function salesForDate(d){return S.sales.filter(x=>x.branch===S.branch&&x.serviceDate===d)}
function stat(name,d){let xs=salesForDate(d).filter(x=>x.therapist===name||x.therapist2===name),now=Date.now(),mins=xs.reduce((a,x)=>{let st=+new Date(x.startAt),en=+new Date(x.endAt);return a+Math.max(0,Math.min(en,now)-st)/60000},0);return{count:xs.length,mins:Math.round(mins),sales:xs.reduce((a,x)=>a+x.total,0),pay:mins/60*35}}
function reportStat(name,d){let xs=salesForDate(d).filter(x=>x.therapist===name||x.therapist2===name),mins=xs.reduce((a,x)=>a+x.minutes,0);return{count:xs.length,mins,sales:xs.reduce((a,x)=>a+x.total,0),pay:mins/60*35}}
function staffSupplyModal(){modal(`<button class="close" onclick="closeM()">×</button><div class="modal-title">${I('bell')}<div><h2>Shop Supplies</h2><span>Report anything that is out of stock or running low.</span></div></div><div class="supply-form"><div class="field"><label>Item / Supply Name</label><input id="supplyName" placeholder="e.g. Massage oil, towels, tissues"></div><div class="field"><label>Status</label><select id="supplyStatus"><option value="out">Out of Stock</option><option value="low">Running Low</option></select></div><div class="field"><label>Note</label><input id="supplyNote" placeholder="Optional note or quantity needed"></div></div><button class="primary fullbtn" onclick="submitSupplyAlert()">${I('bell')} Send to Boss Settings</button><div class="supply-help">This creates a notification for <b>${esc(branches[S.branch].name)}</b>. Boss can review and mark it restocked from Settings.</div>`)}
function submitSupplyAlert(){let n=document.querySelector('#supplyName')?.value.trim(),st=document.querySelector('#supplyStatus')?.value||'out',note=document.querySelector('#supplyNote')?.value.trim()||'';if(!n)return toast('Enter the item name');S.shopSupplies.push({id:Date.now(),branch:S.branch,item:n,status:st,note,date:today(),time:new Date().toISOString(),resolved:false,resolvedDate:''});logActivity('supply','Shop supply alert',`${n} · ${st==='out'?'Out of Stock':'Running Low'}${note?' · '+note:''}`);save();closeM();toast('Supply alert sent to Boss Settings','success');speak(`${n} ${st==='out'?'is out of stock':'is running low'}`)}
function suppliesSettingsPage(){let bf=S.supplyFilterBranch??'all',rows=S.shopSupplies.filter(x=>bf==='all'||String(x.branch)===String(bf)).slice().sort((a,b)=>Number(a.resolved)-Number(b.resolved)||+new Date(b.time)-+new Date(a.time));modal(`<button class="close" onclick="closeM()">×</button><div class="modal-title">${I('bell')}<div><h2>Shop Supplies Alerts</h2><span>Out-of-stock and low-stock notifications from every shop</span></div></div><div class="supply-toolbar"><div class="field"><label>Branch</label><select onchange="S.supplyFilterBranch=this.value;save();closeM();suppliesSettingsPage()"><option value="all">All Branches</option>${branches.map((b,i)=>`<option value="${i}" ${String(bf)===String(i)?'selected':''}>${esc(b.name)}</option>`).join('')}</select></div><div class="supply-legend"><span class="supply-dot out"></span> Out of Stock <span class="supply-dot low"></span> Running Low</div></div><div class="supply-alert-list">${rows.map(x=>`<div class="supply-alert ${x.status} ${x.resolved?'resolved':''}"><div class="supply-alert-icon">${I(x.resolved?'check':'bell')}</div><div class="supply-alert-main"><div><b>${esc(x.item)}</b><span class="supply-status ${x.status}">${x.resolved?'Restocked':x.status==='out'?'Out of Stock':'Running Low'}</span></div><small>${esc(branches[x.branch]?.name||'')} · ${x.date}${x.note?` · ${esc(x.note)}`:''}</small></div><div class="supply-alert-action">${x.resolved?`<span class="restocked-date">Completed ${x.resolvedDate||''}</span><button class="supply-delete" title="Delete completed item" onclick="deleteSupply(${x.id});closeM();suppliesSettingsPage()">×</button>`:`<button class="primary" onclick="resolveSupply(${x.id});closeM();suppliesSettingsPage()">${I('check')} Mark Restocked</button>`}</div></div>`).join('')||'<div class="empty-record">No supply alerts.</div>'}</div>`)}
function deleteSupply(id){let x=S.shopSupplies.find(x=>x.id===id);if(!x||!x.resolved)return;S.shopSupplies=S.shopSupplies.filter(x=>x.id!==id);save();toast('Completed supply alert deleted','success')}
function resolveSupply(id){let x=S.shopSupplies.find(x=>x.id===id);if(!x)return;x.resolved=true;x.resolvedDate=today();save();toast('Marked as restocked','success')}
function handoverExtraQuote(x,originalPaidMins,firstMins,secondMins){
  let combined=Number(firstMins||0)+Number(secondMins||0),extraMins=Math.max(0,combined-Number(originalPaidMins||0));
  let extras=(x.shower?10:0)+(x.deepTissue?10:0),massagePaid=Math.max(0,Number(x.total||0)-extras);
  let perMin=originalPaidMins?massagePaid/originalPaidMins:0;
  return {combined,extraMins,extraAmount:Number((extraMins*perMin).toFixed(2))};
}
function updateHandoverPreview(id){
  let x=S.sales.find(a=>String(a.id)===String(id));if(!x)return;
  let original=Number(x.paidServiceMinutes||x.minutes||0),first=Number(document.querySelector('#editMins')?.value||0),split=!!document.querySelector('#splitOn')?.checked,second=split?Number(document.querySelector('#splitMins')?.value||0):0,q=handoverExtraQuote(x,original,first,second);
  let el=document.querySelector('#handoverPreview');if(!el)return;
  el.className='handover-preview '+(q.extraMins?'over':'ok');
  el.innerHTML=q.extraMins?`<b>Over paid time: +${q.extraMins} min</b><span>Additional amount due before save: <strong>${money(q.extraAmount)}</strong></span><small>Paid ${original} min · Therapist 1 ${first} min · Therapist 2 ${second} min</small>`:`<b>Paid time balanced</b><span>Paid ${original} min · Assigned ${q.combined} min · No additional charge</span>`;
}
function editTreatmentModal(id){
  let x=S.sales.find(a=>String(a.id)===String(id));if(!x)return;
  if(!x.paidServiceMinutes)x.paidServiceMinutes=Number(x.minutes)||0;
  let staff=todaysStaff().map(s=>s.name),paid=Number(x.paidServiceMinutes),current=Math.max(0,Number(x.minutes)||0);
  modal(`<button class="close" onclick="closeM()">×</button><div class="modal-title">${I('edit')}<div><h2>Edit Treatment</h2><span>${esc(x.customer||'Customer')} · paid ${paid} min · ${money(x.total)}</span></div></div>
  <div class="treatment-edit-banner"><b>Payment already received</b><span>When another therapist continues, their minutes are taken from the original therapist first. Extra time is shown before saving.</span></div>
  <div class="formgrid"><div class="field"><label>Therapist</label><select id="editTh" onchange="updateHandoverPreview('${x.id}')">${staff.map(n=>`<option ${n===x.therapist?'selected':''}>${esc(n)}</option>`).join('')}</select></div>
  <div class="field"><label>Paid Service Time</label><input value="${paid} minutes" readonly></div>
  <div class="field fullspan"><label class="toggleline"><span><b>Split / handover to another therapist</b><small>Example: paid 60 min + B continues 30 min → A automatically becomes 30 min.</small></span><input id="splitOn" type="checkbox" onchange="toggleTreatmentSplit('${x.id}')"></label></div></div>
  <div id="splitFields" class="formgrid hidden"><div class="field"><label>Therapist continuing</label><select id="splitTh" onchange="updateHandoverPreview('${x.id}')">${staff.filter(n=>n!==x.therapist).map(n=>`<option>${esc(n)}</option>`).join('')||'<option>No other staff</option>'}</select></div>
  <div class="field"><label>Minutes continuing</label><select id="splitMins" onchange="syncSplitMinutes('${x.id}')">${[15,20,30,45,60,75,90].map(n=>`<option value="${n}" ${n===30?'selected':''}>${n} minutes</option>`).join('')}</select></div>
  <div class="field"><label>Original therapist minutes</label><input id="editMins" type="number" min="0" step="5" value="${current}" oninput="updateHandoverPreview('${x.id}')"></div>
  <div class="field"><label>Handover start</label><input id="splitStart" type="time" value="${fmtTime(new Date(+new Date(x.startAt)+Math.max(0,paid-30)*60000))}"></div></div>
  <div id="handoverPreview" class="handover-preview ok"><b>Paid time unchanged</b><span>${paid} minutes</span></div>
  <button class="primary fullbtn" onclick="saveTreatmentEdit('${x.id}')">${I('check')} Save Treatment Changes</button>`);
}
function toggleTreatmentSplit(id){let on=!!document.querySelector('#splitOn')?.checked;document.querySelector('#splitFields')?.classList.toggle('hidden',!on);if(on)syncSplitMinutes(id);else updateHandoverPreview(id)}
function syncSplitMinutes(id){let x=S.sales.find(a=>String(a.id)===String(id));if(!x)return;let paid=Number(x.paidServiceMinutes||x.minutes||0),second=Number(document.querySelector('#splitMins')?.value||0),first=document.querySelector('#editMins');if(first)first.value=Math.max(0,paid-second);let st=document.querySelector('#splitStart');if(st)st.value=fmtTime(new Date(+new Date(x.startAt)+Math.max(0,paid-second)*60000));updateHandoverPreview(id)}

function saveTreatmentEdit(id){
  let x=S.sales.find(a=>String(a.id)===String(id));if(!x)return;
  let oldTherapist=x.therapist,paid=Number(x.paidServiceMinutes||x.minutes||0),newTherapist=document.querySelector('#editTh')?.value||oldTherapist;
  let split=!!document.querySelector('#splitOn')?.checked,firstMins=split?Number(document.querySelector('#editMins')?.value||0):Number(x.minutes||paid),secondMins=split?Number(document.querySelector('#splitMins')?.value||0):0;
  let q=handoverExtraQuote(x,paid,firstMins,secondMins);
  x.paidServiceMinutes=paid;x.therapist=newTherapist;x.minutes=firstMins;x.endAt=new Date(+new Date(x.startAt)+firstMins*60000).toISOString();
  if(newTherapist!==oldTherapist)x.type='Request';
  x.handoverExtraMinutes=q.extraMins;x.handoverExtraDue=q.extraAmount;

  if(split){
    let th2=document.querySelector('#splitTh')?.value||'';if(!th2||th2==='No other staff'||!secondMins)return toast('Choose the continuing therapist and minutes','danger');
    let baseDate=x.serviceDate||today(),splitStartVal=document.querySelector('#splitStart')?.value||fmtTime(x.endAt),splitStart=new Date(`${baseDate}T${splitStartVal}`);if(isNaN(+splitStart))splitStart=new Date(x.endAt);
    let splitEnd=new Date(+splitStart+secondMins*60000);
    S.sales=S.sales.filter(a=>String(a.continuationOf)!==String(x.id));
    S.sales.push({id:Date.now()+Math.random(),branch:x.branch,customer:x.customer,customer2:x.customer2||'',type:'Request',therapist:th2,therapist2:'',fourHands:false,couple:false,deepTissue:false,room:x.room||null,minutes:secondMins,total:0,tax:0,method:x.method,paidContinuation:true,linkedPaymentId:x.linkedPaymentId||x.id,parentTreatmentId:x.id,continuationOf:x.id,shower:false,startAt:splitStart.toISOString(),endAt:splitEnd.toISOString(),serviceDate:baseDate,extraDue:q.extraAmount,extraMinutes:q.extraMins});
    logActivity('payment','Therapist handover',`${x.customer||'Customer'} · ${newTherapist} ${firstMins} min → ${th2} ${secondMins} min${q.extraMins?` · extra ${q.extraMins} min / ${money(q.extraAmount)} due`:''}`,x.branch,{customer:x.customer,therapist:th2});
  }
  if(newTherapist!==oldTherapist||split){S.nextTurnOverride[S.branch]=S.nextTurnOverride[S.branch]||{};delete S.nextTurnOverride[S.branch][today()]}
  save();closeM();render();tone(760,.16);speak('Treatment updated');toast(q.extraMins?`Saved · ${money(q.extraAmount)} additional payment due`:'Treatment updated','success')
}

function staffPhotoModal(name){window.staffPhotoName=name;modal(`<button class="close" onclick="closeM()">×</button><div class="modal-title">${I('user')}<div><h2>Staff Profile Photo</h2><span>${esc(name)} · saved for this staff name</span></div></div><div class="staff-photo-editor"><div id="photoCropPreview" class="photo-crop-preview"><img src="${S.staffProfiles[name]?.photo||'assets/decorations/default_staff_avatar.svg'}"></div><input id="staffPhotoFile" type="file" accept="image/*" onchange="loadStaffPhoto(this)"><div class="crop-controls"><label>Zoom <input id="photoZoom" type="range" min="1" max="3" step=".05" value="1" oninput="drawStaffCrop()"></label><label>Horizontal <input id="photoX" type="range" min="-100" max="100" value="0" oninput="drawStaffCrop()"></label><label>Vertical <input id="photoY" type="range" min="-100" max="100" value="0" oninput="drawStaffCrop()"></label></div><canvas id="staffCropCanvas" width="320" height="320"></canvas></div><button class="primary fullbtn" onclick="saveStaffPhoto()">${I('check')} Save Profile Photo</button>`)}
function loadStaffPhoto(inp){let f=inp.files?.[0];if(!f)return;let rd=new FileReader();rd.onload=e=>{let im=new Image();im.onload=()=>{window.staffCropImage=im;drawStaffCrop()};im.src=e.target.result};rd.readAsDataURL(f)}
function drawStaffCrop(){let c=document.querySelector('#staffCropCanvas'),im=window.staffCropImage;if(!c||!im)return;let x=c.getContext('2d'),z=+(document.querySelector('#photoZoom')?.value||1),ox=+(document.querySelector('#photoX')?.value||0),oy=+(document.querySelector('#photoY')?.value||0),base=Math.max(c.width/im.width,c.height/im.height),w=im.width*base*z,h=im.height*base*z;x.clearRect(0,0,c.width,c.height);x.drawImage(im,(c.width-w)/2+ox,(c.height-h)/2+oy,w,h);let p=document.querySelector('#photoCropPreview');if(p)p.innerHTML=`<img src="${c.toDataURL('image/jpeg',.88)}">`}
function saveStaffPhoto(){let c=document.querySelector('#staffCropCanvas');if(!c||!window.staffCropImage)return toast('Choose a photo first');S.staffProfiles[window.staffPhotoName]={photo:c.toDataURL('image/jpeg',.86)};save();window.staffCropImage=null;closeM();render();toast('Staff photo saved','success')}
function staff(){let d=today(),branchSales=S.sales.filter(x=>x.branch===S.branch&&x.serviceDate===d),todayRoster=todaysStaff(),names=[...new Set([...todayRoster.map(x=>x.name),...branchSales.flatMap(x=>[x.therapist,x.therapist2].filter(Boolean))])],rows=names.map(n=>{let jobs=branchSales.filter(x=>x.therapist===n||x.therapist2===n),z=stat(n,d),cash=jobs.filter(x=>x.method==='Cash').reduce((a,x)=>a+x.total,0),card=jobs.filter(x=>x.method==='Card').reduce((a,x)=>a+x.total,0);return{name:n,z,jobs,cash,card,total:cash+card}}),totalMins=rows.reduce((a,r)=>a+r.z.mins,0),totalPay=rows.reduce((a,r)=>a+r.z.pay,0),totalCash=rows.reduce((a,r)=>a+r.cash,0),totalCard=rows.reduce((a,r)=>a+r.card,0),totalSales=rows.reduce((a,r)=>a+r.total,0),maxMassage=Math.max(1,...rows.map(r=>r.z.mins)),pending=S.carryovers.filter(c=>!c.paid),returningDebts=S.manualDebts.filter(d=>!d.paid&&names.includes(d.name));return `<div class="panel staff-panel"><div class="headrow"><div><h2>${I('users')} Staff Today</h2><span class="sub">${esc(branches[S.branch].name)} · today's casual staff only · $35/hour</span></div><div class="staff-head-actions staff-top-actions"><button class="secondary-action supplies-btn" class="shop-supplies-btn" onclick="staffSupplyModal()">${I('bell')} Shop Supplies</button><button class="primary addstaff" onclick="staffModal()">${I('plus')} Add Staff</button></div></div><div class="staff-instruction">${I('receipt')}<div><b>Daily reset</b><span>Staff names and today's working screen reset each new day. Historical records remain available only in Boss Reports and Settings.</span></div></div><div class="staff-summary"><div class="stat">${I('users')}<span>Total Staff</span><b>${rows.length}</b></div><div class="stat">${I('clock')}<span>Total Massage Hours</span><b>${(totalMins/60).toFixed(2)} hr</b></div><div class="stat">${I('cash')}<span>Total Wages</span><b>${money(totalPay)}</b></div></div>${pending.length?`<div class="carry-banner"><b>Outstanding Staff Payments</b><span>${pending.length} outstanding payment(s) remain in Boss records.</span></div>`:''}<div class="staff-detail-list">${rows.map((r,i)=>`<details class="staff-detail"><summary><span class="staff-rank">${i+1}</span><b>${esc(r.name)}</b><span>${r.z.count} customers</span><span>${(r.z.mins/60).toFixed(2)} hr</span><strong>${money(r.z.pay)}</strong></summary><div class="staff-jobs">${r.jobs.map(x=>`<div><span><b>${esc(x.customer)}</b><small>${x.minutes} min · ${fmtTime(x.startAt)}–${fmtTime(x.endAt)}</small></span><span class="payment-chip ${x.method.toLowerCase()}">${I(x.method==='Cash'?'cash':'card')} ${x.method}</span><strong>${money(x.total)}</strong></div>`).join('')||'<p>No customers yet today.</p>'}<div class="staff-person-total"><div><span>${I('clock')} Hours</span><b>${(r.z.mins/60).toFixed(2)} hr</b></div><div><span>${I('cash')} Cash</span><b>${money(r.cash)}</b></div><div><span>${I('card')} Card</span><b>${money(r.card)}</b></div><div><span>Total Sales</span><b>${money(r.total)}</b></div><div><span>Wage Due</span><b>${money(r.z.pay)}</b></div></div><div class="staff-payment-sections"><div class="outstanding-entry transfer-entry"><div><b>Bank Transfer Outstanding</b><small>Use only when this staff member receives / is due a bank transfer.</small></div><div class="field"><label>Outstanding Type</label><select id="outMethod_${i}"><option value="Card">Card / Transfer</option><option value="Cash">Cash</option></select></div><div class="field"><label>Transfer amount</label><input id="out_${i}" type="number" inputmode="decimal" min="0" step="0.01" value="${r.z.pay.toFixed(2)}"></div><button class="carry-btn" onclick="carryStaffPay('${esc(r.name)}',+document.querySelector('#out_${i}').value||0,document.querySelector('#outMethod_${i}').value)">${I('clock')} Outstanding Staff Payments</button></div><div class="manual-debt-entry"><div><b>Cash Balance / Other Outstanding</b><small>Separate from bank transfer notifications.</small></div><select id="debtWho_${i}"><option value="store">Store owes staff</option><option value="staff">Staff owes store</option></select><input id="debtAmt_${i}" type="number" inputmode="decimal" min="0" step="0.01" placeholder="$ Amount"><button class="save-balance-btn" onclick="addManualDebt('${esc(r.name)}',document.querySelector('#debtWho_${i}').value,+document.querySelector('#debtAmt_${i}').value||0)">${I('plus')} Save Balance</button></div></div></div></details>`).join('')}</div>${returningDebts.length?`<div class="returning-debts"><h3>${I('bell')} Cash Balance / Other Outstanding</h3><p>These balances followed the staff member back into today's Staff page.</p>${returningDebts.map(d=>`<div class="returning-debt-row"><span><b>${esc(d.name)}</b><small>${d.date} · ${esc(branches[d.branch]?.name||'')} · ${d.who==='store'?'Store owes staff':'Staff owes store'}</small></span><strong>${money(d.amount)}</strong><button class="primary mini" onclick="markManualDebtPaid(${d.id})">${I('check')} Mark Complete</button></div>`).join('')}</div>`:''}<div class="staff-turn-order"><div class="staff-turn-order-head"><div><h3>Today's Turn Order</h3><span>Choose who is 1st, 2nd, 3rd… then save. Staff Availability and Next Turn update from this order.</span></div><button class="primary turn-save-btn" onclick="saveTodayTurnOrder()">${I('check')} Save Order</button></div><div class="turn-order-grid">${todaysStaff().map((s,i)=>`<div class="turn-order-item"><span class="turn-number">${i+1}</span><b>${esc(s.name)}</b><select data-turn-name="${esc(s.name)}">${todaysStaff().map((_,j)=>`<option value="${j+1}" ${j===i?'selected':''}>Turn ${j+1}</option>`).join('')}</select></div>`).join('')}</div></div><div class="massage-hours"><h3>Massage Hours by Staff</h3>${rows.map(r=>`<div class="massage-row"><button class="staff-avatar-btn" onclick="staffPhotoModal('${esc(r.name)}')" title="Choose staff photo"><img src="${S.staffProfiles[r.name]?.photo||'assets/decorations/default_staff_avatar.svg'}" alt="${esc(r.name)}"></button><b>${esc(r.name)}</b><div class="bartrack"><i style="width:${Math.max(3,r.z.mins/maxMassage*100)}%"></i></div><span>${(r.z.mins/60).toFixed(2)} hr</span><strong>${money(r.z.pay)}</strong></div>`).join('')||'<p class="sub">No massage time yet.</p>'}</div><div class="staff-day-total"><h3>Today's Staff Total</h3><div><span>${I('clock')} Massage Hours <b>${(totalMins/60).toFixed(2)} hr</b></span><span>${I('cash')} Cash <b>${money(totalCash)}</b></span><span>${I('card')} Card <b>${money(totalCard)}</b></span><span>Total Sales <b>${money(totalSales)}</b></span><span>Wages <b>${money(totalPay)}</b></span></div></div><div class="staff-footer-actions"><button class="secondary-action" onclick="capturePage('Staff Summary')">${I('receipt')} Save Image</button><button class="secondary-action" onclick="shareSummary('staff')">${I('mail')} Send Summary</button></div></div>`}

function carryStaffPay(name,amount,method='Card'){if(!amount)return toast('No wage to carry');let exists=S.carryovers.some(c=>!c.paid&&c.name===name&&c.date===today()&&c.branch===S.branch);if(exists)return toast('This payment is already carried');S.carryovers.push({id:Date.now(),name,amount,date:today(),branch:S.branch,paid:false,type:'transfer',method});logActivity('outstanding','Outstanding staff payment',`${name} · ${method} · ${money(amount)}`);save();render();tone(650,.15);toast('Boss notification: outstanding transfer added','success')}
function addManualDebt(name,who,amount){if(!amount)return toast('Enter an amount');S.manualDebts.push({id:Date.now(),name,who,amount,date:today(),branch:S.branch,paid:false,method:'Cash'});logActivity('outstanding','Cash Balance / Other Outstanding',`${name} · ${who==='store'?'Store owes staff':'Staff owes store'} · ${money(amount)}`);save();render();tone(650,.18);speak('Cash balance outstanding saved');toast('Boss notification: cash balance saved','success')}
function markManualDebtPaid(id){let d=S.manualDebts.find(x=>x.id==id);if(d){d.paid=true;d.paidDate=today();logActivity('complete','Cash balance completed',`${d.name} · ${money(d.amount)}`,d.branch);save();render();tone(760,.18);speak('Cash balance marked complete');toast('Balance marked complete','success')}}
function markCarryPaid(id){let c=S.carryovers.find(x=>x.id==id);if(c){c.paid=true;c.paidDate=today();logActivity('complete','Staff payment completed',`${c.name} · ${money(c.amount)}`,c.branch);save();render();tone(760,.18);speak('Outstanding staff payment completed');toast('Outstanding payment marked paid','success')}}
function removeStaff(name){S.staff=S.staff.filter(x=>x.name!==name);save();render();toast('Staff removed')}

function addStaffEverywhere(name){
  name=String(name||'').trim();if(!name)return;
  let d=today(), arr=S.staffScheduleByBranch[S.branch]||(S.staffScheduleByBranch[S.branch]={}), plan=arr[d]||(arr[d]=[]);
  if(!plan.some(x=>String(x.name||x).toLowerCase()===name.toLowerCase()))plan.push({name,date:d,order:plan.length+1,source:'staff'});
  syncRosterDate(S.branch,d);save();toast('Staff added to Today, Boss Staff and Availability','success');
}
function saveTodayTurnOrder(){
  let current=todaysStaff().map(x=>typeof x==='string'?{name:x,date:today()}:x).filter(x=>x&&x.name);
  let controls=[...document.querySelectorAll('[data-turn-name]')];
  let byPos=new Map(),used=new Set();
  controls.forEach(e=>{let n=e.dataset.turnName,pos=Math.max(1,Math.min(current.length,+e.value||1));if(!used.has(n)&&!byPos.has(pos)){byPos.set(pos,n);used.add(n)}});
  let ordered=[];
  for(let pos=1;pos<=current.length;pos++){if(byPos.has(pos))ordered.push(byPos.get(pos));else{let free=current.find(x=>!used.has(x.name));if(free){ordered.push(free.name);used.add(free.name)}}}
  let map=new Map(current.map(x=>[x.name,x]));
  let plan=ordered.map((name,i)=>({...map.get(name),name,date:today(),order:i+1,source:(map.get(name)?.source||'staff')}));
  S.staffScheduleByBranch[S.branch]=S.staffScheduleByBranch[S.branch]||{};
  S.staffScheduleByBranch[S.branch][today()]=plan;
  S.staffByBranch[S.branch]=(S.staffByBranch[S.branch]||[]).filter(x=>(x.date||today())!==today()).concat(plan);
  S.nextTurnOverride=S.nextTurnOverride||{};
  if(S.nextTurnOverride[S.branch])delete S.nextTurnOverride[S.branch][today()];
  save();render();tone(720,.12);toast('Turn order saved — Staff Today, Reception and Next Turn updated','success');speak('Staff turn order saved');
}
function staffModal(){modal(`<button class="close" onclick="closeM()">×</button><div class="modal-title">${I('users')}<div><h2>Add Casual Staff</h2></div></div><div class="field"><label>Staff Name</label><input id="sn"></div><button class="primary fullbtn" onclick="if(sn.value.trim()){addStaffEverywhere(sn.value.trim());closeM();render();speak('Staff saved')}">${I('plus')} Add Staff</button>`)}
function statusFor(x){let n=Date.now(),st=+new Date(x.startAt),en=+new Date(x.endAt),left=Math.max(0,Math.ceil((en-n)/60000));if(n>=en)return['Finished','done'];if(n>=st&&left<=15)return[`${left} min left`,'soon'];if(n>=st)return[`${left} min left`,'progress'];let until=Math.ceil((st-n)/60000);return[until<=60?`Starts in ${until} min`:'Upcoming','upcoming']}
function customers(){let rows=S.sales.filter(x=>x.branch===S.branch&&x.serviceDate===today()).slice().reverse(),turnStaff=todaysStaff().map(x=>x.name),todaySales=S.sales.filter(x=>x.branch===S.branch&&x.serviceDate===today()),nextTurn=nextTurnStaffName();return `<div class="panel"><div class="customer-head-row"><div class="section-title">${I('users')}<div><h2>Customers & Treatments</h2><span>Live treatment status, room and payment details</span></div></div>${nextTurn?`<button type="button" class="next-turn-card" onclick="advanceNextTurn()">${I('users')}<span><small>NEXT TURN · TAP TO ADVANCE</small><b>${esc(nextTurn)}</b><em>${turnStaff.length} staff · ${todaySales.length} treatment${todaySales.length===1?'':'s'} today</em></span><strong>›</strong></button>`:''}</div><div class="tablewrap"><table><tr><th>Customer</th><th>Type</th><th>Therapist</th><th>Service</th><th>Start / Finish</th><th>Status</th><th>Room</th><th>Payment</th></tr>${rows.map(x=>{let s=statusFor(x);return `<tr><td><b>${esc(x.customer)}</b></td><td><span class="customer-type ${String(x.type).toLowerCase().replace(/[^a-z]/g,'')}">${esc(x.type)}</span></td><td>${esc(x.therapist)}${x.therapist2?` + ${esc(x.therapist2)}`:''}</td><td><div class="service-detail"><b>${x.minutes} min</b>${x.shower?`<span class="shower-chip">+ Shower Room · $10</span>`:''}${x.deepTissue?`<span class="deep-chip">+ Deep Tissue · $10</span>`:''}${x.fourHands?`<span class="fourhands-chip">Couple</span>`:''}</div></td><td>${fmtTime(x.startAt)} → ${fmtTime(x.endAt)}</td><td><span class="badge ${s[1]}">${I(s[1]==='done'?'check':s[1]==='soon'?'bell':'clock')} ${s[0]}</span></td><td><span class="room-chip">${I('home')} Room ${x.room||'-'}</span></td><td><button class="payment-detail-btn ${x.method.toLowerCase()}" onclick="customerPaymentDetail('${x.id}')">${I(x.method==='Cash'?'cash':'card')} ${x.method}</button><div class="customer-treatment-actions"><button class="treatment-edit-btn" onclick="editTreatmentModal('${x.id}')">${I('edit')} Edit Treatment</button><button class="editextend extend-action-btn" onclick="extendModal('${x.id}')">${I('plus')} Extend</button></div></td></tr>`}).join('')||'<tr><td colspan="8">No customer treatments yet.</td></tr>'}</table></div>${S.bookings.filter(b=>b.branch===S.branch&&b.date===today()&&!b.paid&&b.status!=='Cancelled').length?`<h3 class="customer-booking-history-title">Today's Bookings</h3><div class="customer-booking-cards">${S.bookings.filter(b=>b.branch===S.branch&&b.date===today()&&!b.paid&&b.status!=='Cancelled').map(b=>`<div class="customer-booking-card"><div><b>${esc(b.name||'Booking')}</b><small>${b.time} · ${esc(b.phone||'No phone')}</small></div><div class="booking-customer-service"><span class="service-main-chip">${esc(b.service)}</span>${b.shower?'<span class="shower-chip">+ Shower Room</span>':''}${b.deepTissue?'<span class="deep-chip">+ Deep Tissue</span>':''}${b.couple?'<span class="fourhands-chip">Couple</span>':''}</div><span class="badge ${b.status==='Late'?'late':'upcoming'}">${b.status==='Late'?'Late':'Booked'}</span></div>`).join('')}</div>`:''}${S.bookings.filter(b=>b.branch===S.branch&&b.date===today()&&b.status==='Cancelled').length?`<h3 class="customer-booking-history-title">Cancelled Bookings</h3><div class="cancelled-customer-list">${S.bookings.filter(b=>b.branch===S.branch&&b.date===today()&&b.status==='Cancelled').map(b=>`<div><span>${I('calendar')}<b>${esc(b.name||'Booking')}</b><small>${b.time} · ${esc(b.phone||'No phone')}</small></span><em>Cancelled</em></div>`).join('')}</div>`:''}</div>`}
function customerPaymentDetail(id){let x=S.sales.find(s=>String(s.id)===String(id));if(!x)return;let serviceBase=x.total-(x.shower?10:0)-(x.deepTissue?10:0);modal(`<button class="close" onclick="closeM()">×</button><div class="modal-title">${I(x.method==='Cash'?'cash':'card')}<div><h2>Payment Details</h2><span>${esc(x.customer)} · Room ${x.room||'-'}</span></div></div><div class="payment-detail-card"><div><span>Payment Method</span><b class="payment-chip ${x.method.toLowerCase()}">${I(x.method==='Cash'?'cash':'card')} ${x.method}</b></div><div><span>Massage Service</span><b>${x.minutes} min · ${money(serviceBase)}</b></div>${x.shower?`<div class="shower-line"><span>Shower Room</span><b>+$10.00</b></div>`:''}${x.deepTissue?`<div class="deep-line"><span>Deep Tissue Massage</span><b>+$10.00</b></div>`:''}${x.fourHands?`<div><span>4 Hands Massage</span><b>Included in total</b></div>`:''}<div><span>Total Paid</span><strong>${money(x.total)}</strong></div></div><button class="primary fullbtn" onclick="closeM()">Close</button>`)}

function extendModal(id){let x=S.sales.find(s=>String(s.id)===String(id));if(!x)return;let left=Math.max(0,Math.ceil((+new Date(x.endAt)-Date.now())/60000));modal(`<button class="close" onclick="closeM()">×</button><div class="modal-title">${I('clock')}<div><h2>Extend Treatment</h2><span>${esc(x.customer)} · ${esc(x.therapist)} · ${left} min remaining</span></div></div><div class="extend-grid">${[15,30,45,60].map(m=>`<button onclick="applyExtend('${x.id}',${m})"><b>+ ${m} min</b><small>${money((S.prices.find(p=>p.m===m)||{p:m===15?30:m===30?60:m===45?75:90}).p)}</small></button>`).join('')}</div><p class="sub">The finish time, massage hours and staff wage will update automatically.</p>`)}
function applyExtend(id,m){let x=S.sales.find(s=>String(s.id)===String(id));if(!x)return;let add=(S.prices.find(p=>p.m===m)||{p:m===15?30:m===30?60:m===45?75:90}).p;x.minutes+=m;x.total+=add;x.endAt=new Date(+new Date(x.endAt)+m*60000).toISOString();save();closeM();render();speak(`Treatment extended by ${m} minutes`);toast(`Extended ${m} minutes`,'success')}
function pinGate(title,desc,kind='boss'){let isRec=kind==='reception';return `<div class="panel bosslock bosslock-premium"><div class="boss-lock-icon">${I('lock')}</div><h2>${title}</h2>${desc?`<p>${desc}</p>`:''}<div class="boss-pin-wrap"><input id="pin" class="masked-numeric" type="password" readonly maxlength="4" placeholder="••••"><button class="eye boss-eye" onclick="toggleBossPin()">${I('eye')}</button></div><div id="bossPinError" class="pin-error hidden">Incorrect PIN. Please try again.</div><div class="keypad boss-pinpad premium-pinpad">${['1','2','3','4','5','6','7','8','9'].map(k=>`<button onclick="protectedPinKey('${k}','${kind}')"><span>${k}</span></button>`).join('')}<button class="pin-blank" disabled></button><button onclick="protectedPinKey('0','${kind}')"><span>0</span></button><button class="pin-back" onclick="protectedPinKey('back','${kind}')">${I('back')}</button></div><button class="primary fullbtn boss-unlock" onclick="unlockProtected('${kind}')">${I('lock')} Unlock Access</button><small>${isRec?'Staff Availability access only.':'Reports and Settings stay unlocked for this branch until you switch stores.'}</small></div>`}
function protectedPinKey(k,kind){let e=document.querySelector('#pin'),er=document.querySelector('#bossPinError');if(!e)return;if(er)er.classList.add('hidden');if(k==='back'){e.value=e.value.slice(0,-1);return}if(e.value.length<4)e.value+=k;if(e.value.length===4){let correct=kind==='reception'?String(S.receptionPin):String(S.bossPin);if(e.value===correct)setTimeout(()=>unlockProtected(kind),80);else{if(er)er.classList.remove('hidden');tone(180,.16);setTimeout(()=>{if(e)e.value=''},180)}}}
function toggleBossPin(){let e=document.querySelector('#pin'),b=document.querySelector('.boss-eye');if(!e)return;e.type=e.type==='password'?'text':'password';if(b)b.innerHTML=I(e.type==='password'?'eye':'eye_off')}
function availabilityLock(){return pinGate('Staff Availability','','reception')}
function reportLock(){return pinGate('Boss Reports','Enter Boss PIN to view business performance and payroll.','boss')}
function settingsLock(){return pinGate('Boss Settings','Enter Boss PIN to manage store settings.','boss')}
function unlockProtected(kind){let p=document.querySelector('#pin'),correct=kind==='reception'?String(S.receptionPin):String(S.bossPin);if(!p||p.value!==correct){let er=document.querySelector('#bossPinError');if(er)er.classList.remove('hidden');if(p)p.value='';tone(180,.2);return toast('Incorrect PIN','danger')}if(kind==='reception')window.receptionUnlockedBranch=S.branch;else window.bossUnlockedBranch=S.branch;render();speak('Access unlocked')}
function reportSalesDetail(){let d=S.reportDate||today(),xs=S.sales.filter(x=>x.branch===S.branch&&x.serviceDate===d).slice().sort((a,b)=>+new Date(a.startAt)-+new Date(b.startAt)),cash=xs.filter(x=>x.method==='Cash').reduce((a,x)=>a+x.total,0),card=xs.filter(x=>x.method==='Card').reduce((a,x)=>a+x.total,0),shower=xs.filter(x=>x.shower).reduce((a,x)=>a+10,0);modal(`<button class="close" onclick="closeM()">×</button><div class="modal-title report-sales-title">${I('receipt')}<div><h2>Total Sales Details</h2><span>${esc(branches[S.branch].name)}</span></div><input class="datepick" type="date" value="${d}" onchange="S.reportDate=this.value;save();closeM();reportSalesDetail()"></div><div class="sales-detail-summary"><div><span>Total</span><b>${money(cash+card)}</b></div><div><span>${I('cash')} Cash</span><b>${money(cash)}</b></div><div><span>${I('card')} Card</span><b>${money(card)}</b></div><div><span>Shower Room</span><b>${money(shower)}</b></div></div><div class="tablewrap report-sales-detail"><table><tr><th>Time</th><th>Customer</th><th>Therapist</th><th>Service</th><th>Room</th><th>Shower</th><th>Payment</th><th>Paid</th></tr>${xs.map(x=>`<tr><td>${fmtTime(x.startAt)}</td><td><b>${esc(x.customer)}</b></td><td>${esc(x.therapist)}${x.therapist2?` + ${esc(x.therapist2)}`:''}</td><td>${x.minutes} min${x.couple||x.fourHands?' · Couple':''}${x.deepTissue?' · Deep Tissue +$10':''}</td><td><span class="room-chip">Room ${x.room||'-'}</span></td><td>${x.shower?`<span class="shower-chip">Yes · $10</span>`:'<span class="no-shower">No</span>'}</td><td><span class="payment-chip ${x.method.toLowerCase()}">${I(x.method==='Cash'?'cash':'card')} ${x.method}</span></td><td><b>${money(x.total)}</b></td></tr>`).join('')||'<tr><td colspan="8">No sales for this date.</td></tr>'}</table></div>`)}


function liveActivityRows(d){let generated=[];S.bookings.filter(b=>b.date===d).forEach(b=>generated.push({id:'b_'+b.id,at:`${b.date}T${b.time||'00:00'}:00`,branch:b.branch,kind:b.status==='Cancelled'?'cancel':'booking',title:b.status==='Cancelled'?'Booking cancelled':'Booking',detail:`${b.name||'Booking'} · ${b.time}${b.status?' · '+b.status:''}`,customer:b.name||'Booking',phone:b.phone||'',notes:b.notes||'',service:b.service||'',therapist:b.therapist||'',status:b.status||'Booked'}));S.sales.filter(x=>x.serviceDate===d).forEach(x=>generated.push({id:'s_'+x.id,at:x.startAt,branch:x.branch,kind:'payment',title:'Customer payment / treatment',detail:`${x.customer} · ${x.minutes} min · ${x.method} · ${money(x.total)}`,customer:x.customer,service:`${x.minutes} min${x.shower?' + Shower':''}${x.deepTissue?' + Deep Tissue':''}`,therapist:[x.therapist,x.therapist2].filter(Boolean).join(' + '),room:x.room||'',method:x.method,total:x.total,status:'Paid'}));S.carryovers.filter(x=>x.date===d).forEach(x=>generated.push({id:'c_'+x.id,at:`${x.date}T12:00:00`,branch:x.branch,kind:x.paid?'complete':'outstanding',title:x.paid?'Staff payment completed':'Outstanding staff payment',detail:`${x.name} · ${x.method||'Card'} · ${money(x.amount)}`,customer:x.name,method:x.method||'Card',total:x.amount,status:x.paid?'Completed':'Outstanding'}));S.manualDebts.filter(x=>x.date===d).forEach(x=>generated.push({id:'d_'+x.id,at:`${x.date}T12:01:00`,branch:x.branch,kind:x.paid?'complete':'outstanding',title:x.paid?'Cash balance completed':'Cash Balance / Other Outstanding',detail:`${x.name} · ${money(x.amount)}`,customer:x.name,total:x.amount,status:x.paid?'Completed':'Outstanding'}));S.shopSupplies.filter(x=>x.date===d).forEach(x=>generated.push({id:'p_'+x.id,at:x.time||`${x.date}T12:02:00`,branch:x.branch,kind:x.resolved?'complete':'supply',title:x.resolved?'Supply completed':'Shop supply alert',detail:`${x.item}${x.note?' · '+x.note:''}`,service:x.item,notes:x.note||'',status:x.resolved?'Completed':(x.status==='out'?'Out of Stock':'Running Low')}));let logged=(S.activityLog||[]).filter(x=>x.date===d),seen=new Set();return [...logged,...generated].filter(x=>{let k=[x.kind,x.title,x.detail,x.branch].join('|');if(seen.has(k))return false;seen.add(k);return true}).sort((a,b)=>+new Date(b.at)-+new Date(a.at))}
function liveActivityDetail(id){let d=S.reportActivityDate||today(),x=liveActivityRows(d).find(r=>String(r.id)===String(id));if(!x)return toast('Activity detail not found');modal(`<button class="close" onclick="closeM()">×</button><div class="activity-detail-page"><div class="activity-detail-hero ${x.kind}"><div class="activity-detail-icon">${I(activityIcon(x.kind))}</div><div><span>${esc(branches[x.branch]?.name||'')}</span><h2>${esc(x.title)}</h2><p>${new Date(x.at).toLocaleString('en-AU',{dateStyle:'medium',timeStyle:'short'})}</p></div><span class="detail-status">${esc(x.status||x.kind)}</span></div><div class="activity-detail-grid">${x.customer?`<div><span>Customer / Staff</span><b>${esc(x.customer)}</b></div>`:''}${x.phone?`<div><span>Phone</span><b>${esc(x.phone)}</b></div>`:''}${x.service?`<div><span>Service / Item</span><b>${esc(x.service)}</b></div>`:''}${x.therapist?`<div><span>Therapist</span><b>${esc(x.therapist)}</b></div>`:''}${x.room?`<div><span>Room</span><b>Room ${esc(x.room)}</b></div>`:''}${x.method?`<div><span>Payment</span><b class="payment-chip ${String(x.method).toLowerCase()}">${esc(x.method)}</b></div>`:''}${x.total!=null?`<div><span>Amount</span><b>${money(x.total)}</b></div>`:''}${x.notes?`<div class="wide"><span>Notes</span><b>${esc(x.notes)}</b></div>`:''}<div class="wide"><span>Activity Detail</span><b>${esc(x.detail||'')}</b></div></div><button class="secondary-action fullbtn" onclick="closeM();bossLiveActivity()">${I('back')} Back to Live Activity</button></div>`)}
function unreadLiveActivityCount(){let seen=+S.liveActivitySeenAt||0;return liveActivityRows(today()).filter(x=>['booking','cancel','outstanding','supply'].includes(x.kind)&&(+new Date(x.at)>seen)).length}
function bossLiveActivity(){let d=S.reportActivityDate||today(),rows=liveActivityRows(d);if(d===today()){S.liveActivitySeenAt=Date.now();save();}modal(`<button class="close" onclick="closeM()">×</button><div class="modal-title">${I('bell')}<div><h2>All Branches Live Activity</h2><span>Tap any activity to open the full detail page</span></div></div><div class="activity-toolbar"><label>Date <input type="date" value="${d}" onchange="S.reportActivityDate=this.value;save();closeM();bossLiveActivity()"></label><span class="live-pill">● LIVE</span></div><div class="activity-feed">${rows.map((x,i)=>`<button class="activity-item ${x.kind}" onclick="liveActivityDetail('${x.id||('a_'+i)}')"><div class="activity-icon">${I(activityIcon(x.kind))}</div><div><b>${esc(x.title)}</b><span>${esc(x.detail)}</span><small>${esc(branches[x.branch]?.name||'')} · ${new Date(x.at).toLocaleTimeString('en-AU',{hour:'2-digit',minute:'2-digit'})}</small></div><i class="activity-arrow">›</i></button>`).join('')||'<div class="empty-record">No activity for this date.</div>'}</div>`) }

function staffWageDetails(d=S.reportDate||today(),bi=S.branch){
  let branch=branches[bi], xs=S.sales.filter(x=>x.branch===bi&&x.serviceDate===d), names=[...new Set(xs.flatMap(x=>[x.therapist,x.therapist2]).filter(Boolean))];
  let rows=names.map(n=>{let q=xs.filter(x=>x.therapist===n||x.therapist2===n),mins=q.reduce((a,x)=>a+x.minutes,0),pay=mins/60*35;return{name:n,mins,pay,count:q.length}}).sort((a,b)=>b.pay-a.pay);
  let total=rows.reduce((a,x)=>a+x.pay,0);
  modal(`<button class="close" onclick="closeM()">×</button><div class="modal-title">${I('users')}<div><h2>Staff Wages</h2><span>${esc(branch.name)} · ${d}</span></div></div><div class="summary-date-row"><label>Date <input type="date" value="${d}" onchange="staffWageDetails(this.value,${bi})"></label></div><div class="payroll-total-card"><span>Total Staff Wages</span><b>${money(total)}</b></div><div class="tablewrap"><table><tr><th>Staff</th><th>Treatments</th><th>Hours</th><th>Wage</th></tr>${rows.map(r=>`<tr><td><b>${esc(r.name)}</b></td><td>${r.count}</td><td>${(r.mins/60).toFixed(2)} hr</td><td><span class="payment-chip cash">${money(r.pay)}</span></td></tr>`).join('')||'<tr><td colspan="4">No staff wages for this date.</td></tr>'}</table></div><button class="primary fullbtn" onclick="closeM()">${I('back')} Back</button>`)
}
function reports(){let d=S.reportDate,xs=S.sales.filter(x=>x.branch===S.branch&&x.serviceDate===d),cash=xs.filter(x=>x.method==='Cash').reduce((a,x)=>a+x.total,0),card=xs.filter(x=>x.method==='Card').reduce((a,x)=>a+x.total,0),names=[...new Set(xs.map(x=>x.therapist))],stats=names.map(n=>({n,...reportStat(n,d)})),mins=stats.reduce((a,x)=>a+x.mins,0),w=stats.reduce((a,x)=>a+x.pay,0),tot=cash+card,tax=xs.reduce((a,x)=>a+(x.tax||0),0),book=S.bookings.filter(b=>b.branch===S.branch&&b.date===d).length,all=branches.map((b,i)=>{let q=S.sales.filter(x=>x.branch===i&&x.serviceDate===d),sale=q.reduce((a,x)=>a+x.total,0),mi=q.reduce((a,x)=>a+x.minutes,0);return{b,i,sale,cash:q.filter(x=>x.method==='Cash').reduce((a,x)=>a+x.total,0),card:q.filter(x=>x.method==='Card').reduce((a,x)=>a+x.total,0),count:q.length,hours:mi/60,wage:mi/60*35}}).sort((a,b)=>b.sale-a.sale),pending=S.carryovers.filter(c=>!c.paid);return `<div class="panel report-panel"><div class="report-head"><div><h2>${I('bar_chart')} Business Report</h2><span class="sub">${esc(branches[S.branch].name)} · daily report and all-store ranking</span></div><div class="report-actions"><button class="primary live-activity-btn" onclick="bossLiveActivity()">${I('bell')} Live Activity${(()=>{let n=unreadLiveActivityCount();return n?`<i class="corner-notification">${Math.min(99,n)}</i>`:''})()}</button><button class="secondary-action" onclick="capturePage('Business Report')">${I('receipt')} Save Image</button><button class="secondary-action" onclick="shareSummary('report')">${I('mail')} Send</button><input class="datepick" type="date" value="${d}" onchange="S.reportDate=this.value;save();render()"></div></div><div class="cards reportcards"><button class="stat report-click-stat" onclick="reportSalesDetail()">${I('receipt')}<span>Total Sales</span><b>${money(tot)}</b><small>${xs.length} treatments · Tap to view all transactions</small></button><div class="stat">${I('cash')}<span>Cash</span><b>${money(cash)}</b></div><div class="stat">${I('card')}<span>Card</span><b>${money(card)}</b></div><div class="stat">${I('calendar')}<span>Bookings</span><b>${book}</b></div><div class="stat">${I('clock')}<span>Massage Hours</span><b>${(mins/60).toFixed(2)} hr</b></div><button class="stat report-click-stat" onclick="staffWageDetails('${d}',${S.branch})">${I('users')}<span>Staff Wages</span><b>${money(w)}</b><small>Tap to view staff-by-staff payroll</small></button><div class="stat">${I('percent')}<span>Tax Included</span><b>${money(tax)}</b></div><div class="stat">${I('bar_chart')}<span>Net After Wages</span><b>${money(tot-w)}</b></div></div><h3>All Branches Daily Summary</h3><div class="tablewrap"><table><tr><th>Rank</th><th>Branch</th><th>Treatments</th><th>Cash</th><th>Card</th><th>Sales</th><th>Hours</th><th>Wages</th><th>Net</th></tr>${all.map((r,i)=>`<tr><td><span class="rank ${i<3?'toprank':''}">${i===0?'🏆':i===1?'🥈':i===2?'🥉':i+1}</span></td><td><b>${esc(r.b.name)}</b></td><td>${r.count}</td><td><span class="payment-chip cash">${money(r.cash)}</span></td><td><span class="payment-chip card">${money(r.card)}</span></td><td><b>${money(r.sale)}</b></td><td>${r.hours.toFixed(2)}</td><td><span class="payment-chip cash">${money(r.wage)}</span></td><td><button class="small-action payroll-detail-btn" onclick="staffWageDetails('${d}',${r.i})">${I('users')} Staff</button></td><td><b>${money(r.sale-r.wage)}</b></td></tr>`).join('')}</table></div><h3>Staff Payroll Detail</h3><div class="tablewrap"><table><tr><th>Therapist</th><th>Customers</th><th>Hours</th><th>Sales</th><th>Pay Due</th></tr>${stats.map(z=>`<tr><td><b>${esc(z.n)}</b></td><td>${z.count}</td><td>${(z.mins/60).toFixed(2)}</td><td>${money(z.sales)}</td><td><b>${money(z.pay)}</b></td></tr>`).join('')||'<tr><td colspan="5">No staff activity.</td></tr>'}</table></div><h3>Outstanding Staff Payments</h3><div class="tablewrap"><table><tr><th>Staff</th><th>Original Date</th><th>Branch</th><th>Amount</th><th>Status</th></tr>${pending.map(c=>`<tr><td><b>${esc(c.name)}</b></td><td>${c.date}</td><td>${esc(branches[c.branch]?.name||'')}</td><td><b>${money(c.amount)}</b></td><td><button class="mini" onclick="markCarryPaid(${c.id})">Mark Paid</button></td></tr>`).join('')||'<tr><td colspan="5">No outstanding staff payments.</td></tr>'}</table></div><h3>Cash Balance / Other Outstanding</h3><div class="tablewrap"><table><tr><th>Staff</th><th>Date</th><th>Branch</th><th>Type</th><th>Amount</th><th>Status</th></tr>${S.manualDebts.filter(x=>!x.paid).map(d=>`<tr><td><b>${esc(d.name)}</b></td><td>${d.date}</td><td>${esc(branches[d.branch]?.name||'')}</td><td>${d.who==='store'?'Store owes staff':'Staff owes store'}</td><td><b>${money(d.amount)}</b></td><td><button class="mini" onclick="markManualDebtPaid(${d.id})">Mark Complete</button></td></tr>`).join('')||'<tr><td colspan="6">No outstanding cash balances.</td></tr>'}</table></div></div>`}


function weekDates(base=today()){let d=new Date(base+'T12:00:00'),day=(d.getDay()+6)%7;d.setDate(d.getDate()-day);return Array.from({length:7},(_,i)=>{let x=new Date(d);x.setDate(d.getDate()+i);return x.toISOString().slice(0,10)})}
function bossStaffSchedule(bi=S.branch){
  let dates=weekDates(),sched=S.staffScheduleByBranch[bi]||(S.staffScheduleByBranch[bi]={});
  modal(`<button class="close" onclick="closeM()">×</button><div class="modal-title">${I('users')}<div><h2>Staff Schedule</h2><span>Boss weekly roster · all branches</span></div></div><div class="field"><label>Branch</label><select id="bossRosterBranch" onchange="closeM();bossStaffSchedule(+this.value)">${branches.map((b,i)=>`<option value="${i}" ${i===bi?'selected':''}>${esc(b.name)}</option>`).join('')}</select></div><div class="boss-roster-week">${dates.map(d=>{let arr=rosterForDate(bi,d);return `<section class="boss-roster-day ${d===today()?'today':''}"><div class="boss-roster-date"><b>${new Date(d+'T12:00:00').toLocaleDateString('en-AU',{weekday:'short'})}</b><span>${new Date(d+'T12:00:00').toLocaleDateString('en-AU',{day:'2-digit',month:'short'})}</span></div><div class="boss-roster-names" id="bossday_${bi}_${d}">${arr.map((s,i)=>`<div><span class="turn-number">${i+1}</span><input value="${esc(s.name)}" placeholder="Staff name"><button onclick="this.parentElement.remove()">×</button></div>`).join('')}<button class="boss-add-row" onclick="addBossRosterRow('${d}',${bi})">${I('plus')} Add staff</button></div></section>`}).join('')}</div><button class="primary fullbtn" onclick="saveBossStaffSchedule(${bi})">${I('check')} Save Weekly Staff</button>`)
}
function addBossRosterRow(d,bi=S.branch){let box=document.querySelector('#bossday_'+bi+'_'+d),btn=box?.querySelector('.boss-add-row');if(!box||!btn)return;let n=box.querySelectorAll('input').length+1,div=document.createElement('div');div.innerHTML=`<span class="turn-number">${n}</span><input placeholder="Staff name"><button onclick="this.parentElement.remove()">×</button>`;box.insertBefore(div,btn)}
function saveBossStaffSchedule(bi=S.branch){
  weekDates().forEach(d=>{let names=[...document.querySelectorAll('#bossday_'+bi+'_'+d+' input')].map(x=>x.value.trim()).filter(Boolean);S.staffScheduleByBranch[bi][d]=[...new Set(names)].map((name,i)=>({name,date:d,order:i+1,source:'boss'}));syncRosterDate(bi,d)});
  save();closeM();render();toast('Weekly staff schedule saved','success');speak('Weekly staff schedule saved');
}
function settings(){let n=S.carryovers.filter(c=>!c.paid).length+S.manualDebts.filter(c=>!c.paid).length,sn=S.shopSupplies.filter(x=>!x.resolved).length;return `<div class="panel"><div class="section-title">${I('settings')}<div><h2>Settings</h2><span>Boss controls, exports, payroll notifications and store configuration</span></div></div><div class="settings-list"><button onclick="bossStaffSchedule()">${I('users')}<span><b>Staff Schedule</b><small>Plan who works today and this week · controls Staff Today, Availability and turn order</small></span>›</button><button onclick="dataCenterModal()">${I('receipt')}<span><b>Send & Export Data</b><small>Send summary or export ALL sales, bookings, customer records, staff wages and outstanding payments</small></span>›</button><button class="notification-setting" onclick="outstandingPaymentsPage()">${I('clock')}<span><b>Outstanding Staff Payments</b><small>Bank transfer, Cash Balance / Other Outstanding · every branch · complete history</small></span>${n?`<i class="notification-count">${n}</i>`:''}›</button><button class="notification-setting supply-setting" onclick="suppliesSettingsPage()">${I('bell')}<span><b>Shop Supplies Alerts</b><small>Out-of-stock and low-stock items from every branch · restock history</small></span>${sn?`<i class="notification-count">${sn}</i>`:''}›</button><button onclick="allBranchesSummary()">${I('bar_chart')}<span><b>All Branches Daily Summary</b><small>Compare daily sales, payments, treatments and staff wages across every store · choose any date</small></span>›</button><button onclick="priceSettings()">${I('edit')}<span><b>Service Prices</b><small>Edit prices for this store only</small></span>›</button><button onclick="branchPinSettings()">${I('lock')}<span><b>Branch PINs</b><small>Branch login + separate Reception and Boss PINs</small></span>›</button><button onclick="taxSettings()">${I('percent')}<span><b>Tax & E-Receipt</b><small>Enable tax, set rate and e-receipt option</small></span>›</button><div class="setting-switch">${I('volume')}<span><b>Notifications & Sound</b><small>English payment, booking and save sounds</small></span><label class="switch"><input type="checkbox" ${S.soundEnabled?'checked':''} onchange="S.soundEnabled=this.checked;save();if(this.checked){speak('Sound enabled');toast('Sound enabled','success')}else toast('Sound disabled')"><i></i></label></div><button onclick="login()">${I('home')}<span><b>Switch Branch</b><small>Return to branch selection</small></span>›</button></div></div>`}
function allBranchesSummary(){let d=S.reportDate||today(),rows=branches.map((b,i)=>{let q=S.sales.filter(x=>x.branch===i&&x.serviceDate===d),mins=q.reduce((a,x)=>a+x.minutes,0),sale=q.reduce((a,x)=>a+x.total,0);return{b,i,sale,count:q.length,cash:q.filter(x=>x.method==='Cash').reduce((a,x)=>a+x.total,0),card:q.filter(x=>x.method==='Card').reduce((a,x)=>a+x.total,0),hours:mins/60,wage:mins/60*35}}).sort((a,b)=>b.sale-a.sale);modal(`<button class="close" onclick="closeM()">×</button><div class="modal-title">${I('bar_chart')}<div><h2>All Branches Daily Summary</h2><span>View any date · ranked by total sales</span></div></div><div class="summary-date-row"><label>Date <input type="date" value="${d}" onchange="S.reportDate=this.value;save();closeM();allBranchesSummary()"></label></div><div class="tablewrap"><table><tr><th>Rank</th><th>Branch</th><th>Treatments</th><th>Cash</th><th>Card</th><th>Sales</th><th>Hours</th><th>Wages</th><th>Staff Payroll</th><th>Net</th></tr>${rows.map((r,i)=>`<tr><td><b>${i+1}</b></td><td><b>${esc(r.b.name)}</b></td><td>${r.count}</td><td>${money(r.cash)}</td><td>${money(r.card)}</td><td><b>${money(r.sale)}</b></td><td>${r.hours.toFixed(2)}</td><td>${money(r.wage)}</td><td><button class="small-action payroll-detail-btn" onclick="staffWageDetails('${d}',${r.i})">${I('users')} Staff</button></td><td><b>${money(r.sale-r.wage)}</b></td></tr>`).join('')}</table></div>`)}

function outstandingPaymentsPage(){let bd=S.outstandingBranch??'all',dt=S.outstandingDate||'',all=S.carryovers.filter(c=>(bd==='all'||String(c.branch)===String(bd))&&(!dt||c.date===dt)).slice().reverse();modal(`<button class="close" onclick="closeM()">×</button><div class="modal-title">${I('clock')}<div><h2>Outstanding Staff Payments</h2><span>Bank transfer / PayID records from every branch and any date</span></div></div><div class="outstanding-filters"><div class="field"><label>Branch</label><select onchange="S.outstandingBranch=this.value;save();closeM();outstandingPaymentsPage()"><option value="all" ${bd==='all'?'selected':''}>All Branches</option>${branches.map((b,i)=>`<option value="${i}" ${String(bd)===String(i)?'selected':''}>${esc(b.name)}</option>`).join('')}</select></div><div class="field"><label>Date (optional)</label><input type="date" value="${dt}" onchange="S.outstandingDate=this.value;save();closeM();outstandingPaymentsPage()"></div><button class="secondary-action" onclick="S.outstandingDate='';S.outstandingBranch='all';save();closeM();outstandingPaymentsPage()">Clear Filters</button></div><div class="outstanding-history">${all.map(c=>{let k=`${c.branch}_${c.name}`,p=S.staffPaymentDetails[k]||{};return `<details class="payment-history ${c.paid?'complete':''}"><summary><span>${c.paid?'✓':'!'}</span><b>${esc(c.name)}</b><small>${c.date} · ${esc(branches[c.branch]?.name||'')}</small><strong>${money(c.amount)}</strong><em><span class="out-method ${(c.method||'Card').toLowerCase()}">${I((c.method||'Card')==='Cash'?'cash':'card')} ${c.method||'Card'}</span> ${c.paid?'Completed':'Outstanding'}</em></summary><div class="payment-detail-grid"><p><b>Created:</b> ${c.date}</p><p><b>Branch:</b> ${esc(branches[c.branch]?.name||'')}</p><div class="field"><label>Bank / PayID</label><input id="payid_${c.id}" value="${esc(p.payid||'')}" placeholder="PayID, mobile, email or bank note"></div><div class="field"><label>Account / Reference</label><input id="bank_${c.id}" value="${esc(p.bank||'')}" placeholder="Bank / BSB / account reference"></div><button class="secondary-action" onclick="saveStaffPaymentDetail('${k}',${c.id})">${I('check')} Save Staff Payment Info</button>${c.paid?`<div class="completed-record-actions"><p class="complete-note">Completed: ${c.paidDate||''}</p><button class="record-delete-x" title="Delete completed record" onclick="deleteCarryover(${c.id});closeM();outstandingPaymentsPage()">×</button></div>`:`<button class="primary" onclick="markCarryPaid(${c.id});closeM();outstandingPaymentsPage()">Mark as Completed</button>`}</div></details>`}).join('')||'<div class="empty-record">No bank-transfer records match this branch/date.</div>'}</div><h3 class="outstanding-subhead">Cash Balance / Other Outstanding</h3><div class="outstanding-history manual-history">${S.manualDebts.filter(d=>(bd==='all'||String(d.branch)===String(bd))&&(!dt||d.date===dt)).slice().reverse().map(d=>`<details class="payment-history cash ${d.paid?'complete':''}"><summary><span>${d.paid?'✓':'!'}</span><b>${esc(d.name)}</b><small>${d.date} · ${esc(branches[d.branch]?.name||'')}</small><strong>${money(d.amount)}</strong><em><span class="out-method cash">${I('cash')} Cash</span> ${d.paid?'Completed':'Outstanding'}</em></summary><div class="payment-detail-grid"><p><b>Type:</b> ${d.who==='store'?'Store owes staff':'Staff owes store'}</p><p><b>Original branch:</b> ${esc(branches[d.branch]?.name||'')}</p>${d.paid?`<p class="complete-note">Completed: ${d.paidDate||''}</p>`:`<button class="primary" onclick="markManualDebtPaid(${d.id});closeM();outstandingPaymentsPage()">${I('check')} Mark Complete</button>`}</div></details>`).join('')||'<div class="empty-record">No cash balances match this branch/date.</div>'}</div>`)}
function deleteCarryover(id){let c=S.carryovers.find(x=>x.id===id);if(!c||!c.paid)return;S.carryovers=S.carryovers.filter(x=>x.id!==id);save();toast('Completed outstanding payment deleted','success')}
function saveStaffPaymentDetail(key,id){S.staffPaymentDetails[key]={payid:document.querySelector('#payid_'+id)?.value.trim()||'',bank:document.querySelector('#bank_'+id)?.value.trim()||''};save();toast('Staff bank / PayID information saved','success')}

function openSMS(phone,body){phone=(phone||'').replace(/[^\d+]/g,'');if(!phone)return toast('Enter a mobile number');let sep=/iPad|iPhone|iPod/.test(navigator.userAgent)?'&':'?';window.location.href=`sms:${encodeURIComponent(phone)}${sep}body=${encodeURIComponent(body)}`}
function summaryPlain(kind){let d=kind==='report'?(S.reportDate||today()):today(),xs=S.sales.filter(x=>x.serviceDate===d&&(kind==='branches'||x.branch===S.branch)),sales=xs.reduce((a,x)=>a+x.total,0),mins=xs.reduce((a,x)=>a+x.minutes,0),w=mins/60*35;return `Eternity Thai Massage\n${kind==='report'?'Business Report':kind==='staff'?'Staff Summary':'All Stores Summary'}\nDate: ${d}\nTotal Sales: ${money(sales)}\nMassage Hours: ${(mins/60).toFixed(2)} hr\nStaff Wages: ${money(w)}\nNet After Wages: ${money(sales-w)}`}
function shareSummary(kind){modal(`<button class="close" onclick="closeM()">×</button><div class="modal-title">${I('mail')}<div><h2>Send Summary</h2><span>Send by SMS or email</span></div></div><div class="field"><label>Mobile</label><input id="sumPhone" type="tel" inputmode="tel" placeholder="04xx xxx xxx"></div><div class="field"><label>Email</label><input id="sumEmail" type="email" placeholder="name@example.com"></div><div class="receipt-actions"><button class="primary" onclick="openSMS(document.querySelector('#sumPhone').value,summaryPlain('${kind}'))">${I('phone')} Send SMS</button><button class="primary" onclick="let e=document.querySelector('#sumEmail').value.trim();if(!e)return toast('Enter email');location.href='mailto:'+encodeURIComponent(e)+'?subject='+encodeURIComponent('Eternity Massage Summary')+'&body='+encodeURIComponent(summaryPlain('${kind}'))">${I('mail')} Send Email</button></div>`)}
function capturePage(title){let d=title.includes('Report')?(S.reportDate||today()):today(),xs=S.sales.filter(x=>x.branch===S.branch&&x.serviceDate===d),sale=xs.reduce((a,x)=>a+x.total,0),mins=xs.reduce((a,x)=>a+x.minutes,0),isStaff=title.includes('Staff'),staffNames=[...new Set(xs.flatMap(x=>[x.therapist,x.therapist2].filter(Boolean)))],staffRows=staffNames.map(n=>{let jobs=xs.filter(a=>a.therapist===n||a.therapist2===n),sm=jobs.reduce((a,j)=>a+j.minutes,0),cash=jobs.filter(j=>j.method==='Cash').reduce((a,j)=>a+j.total,0),card=jobs.filter(j=>j.method==='Card').reduce((a,j)=>a+j.total,0);return{name:n,mins:sm,cash,card,sales:cash+card,wage:sm/60*35}}),h=isStaff?Math.max(760,330+staffRows.length*52):700,c=document.createElement('canvas');c.width=1100;c.height=h;let x=c.getContext('2d');x.fillStyle='#f7f1e8';x.fillRect(0,0,c.width,c.height);x.strokeStyle='#b99b7c';x.lineWidth=2;x.strokeRect(28,28,1044,h-56);x.fillStyle='#5b3b28';x.font='bold 42px Arial';x.fillText(title,60,90);x.font='24px Arial';x.fillText(branches[S.branch]?.name||'',60,132);x.fillText(`Date: ${d}`,60,168);if(isStaff){x.font='bold 20px Arial';x.fillText('Staff',60,225);x.fillText('Hours',380,225);x.fillText('Cash',500,225);x.fillText('Card',630,225);x.fillText('Revenue',760,225);x.fillText('Wage',910,225);x.strokeStyle='#d4c0aa';x.beginPath();x.moveTo(60,240);x.lineTo(1025,240);x.stroke();x.font='19px Arial';staffRows.forEach((r,i)=>{let y=278+i*48;x.fillStyle='#4f3a2b';x.fillText(r.name,60,y);x.fillText((r.mins/60).toFixed(2),380,y);x.fillText(money(r.cash),500,y);x.fillText(money(r.card),630,y);x.fillText(money(r.sales),760,y);x.fillText(money(r.wage),910,y)});let y=300+staffRows.length*48;x.fillStyle='#eadccb';x.fillRect(55,y-30,980,145);x.fillStyle='#4b3425';x.font='bold 22px Arial';x.fillText("Today's Staff Total",75,y+5);x.font='20px Arial';x.fillText(`Revenue: ${money(sale)}`,75,y+45);x.fillText(`Cash: ${money(xs.filter(a=>a.method==='Cash').reduce((a,b)=>a+b.total,0))}`,340,y+45);x.fillText(`Card: ${money(xs.filter(a=>a.method==='Card').reduce((a,b)=>a+b.total,0))}`,570,y+45);x.fillText(`Hours: ${(mins/60).toFixed(2)} hr`,75,y+82);x.fillText(`Wages: ${money(staffRows.reduce((a,r)=>a+r.wage,0))}`,340,y+82)}else{let lines=[`Total Sales: ${money(sale)}`,`Treatments: ${xs.length}`,`Massage Hours: ${(mins/60).toFixed(2)} hr`,`Staff Wages: ${money(mins/60*35)}`];lines.forEach((t,i)=>x.fillText(t,60,225+i*58))}window.captureData=c.toDataURL('image/png');modal(`<button class="close" onclick="closeM()">×</button><div class="modal-title">${I('receipt')}<div><h2>Image Preview</h2><span>Preview before saving or sending.</span></div></div><div class="capture-preview"><img src="${window.captureData}" alt="Summary preview"></div><div class="field"><label>Mobile for SMS</label><input id="capturePhone" type="tel" inputmode="tel" placeholder="04xx xxx xxx"></div><div class="receipt-actions"><button class="primary" onclick="saveCapture('${title.replace(/'/g,'')}')">${I('check')} Save Image</button><button class="primary" onclick="openSMS(document.querySelector('#capturePhone').value,'${title.replace(/'/g,'')} - '+branches[S.branch].name+' - '+d+'\\nPlease attach the saved report image to this message.')">${I('phone')} Send SMS</button></div>`)}

function saveCapture(title){if(!window.captureData)return toast('No preview available');let a=document.createElement('a');a.href=window.captureData;a.download=`${title.replace(/\s+/g,'_')}_${today()}.png`;a.click();toast('Image saved','success')}
function downloadBlob(name,text,type){let b=new Blob([text],{type}),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),500);toast(name+' exported','success')}
function csvCell(v){return '"'+String(v??'').replace(/"/g,'""')+'"'}
function exportTotals(){let sales=S.sales.reduce((a,x)=>a+(+x.total||0),0),cash=S.sales.filter(x=>x.method==='Cash').reduce((a,x)=>a+(+x.total||0),0),card=S.sales.filter(x=>x.method==='Card').reduce((a,x)=>a+(+x.total||0),0),mins=S.sales.reduce((a,x)=>a+(+x.minutes||0),0),wages=mins/60*35,outTransfer=S.carryovers.filter(x=>!x.paid).reduce((a,x)=>a+(+x.amount||0),0),outCash=S.manualDebts.filter(x=>!x.paid).reduce((a,x)=>a+(+x.amount||0),0);return{sales,cash,card,mins,wages,net:sales-wages,outTransfer,outCash,outstanding:outTransfer+outCash}}
function downloadCsv(){let t=exportTotals(),rows=[['ETERNITY MASSAGE POS - BUSINESS EXPORT'],[],['BUSINESS TOTALS'],['Total Sales',t.sales],['Cash Sales',t.cash],['Card Sales',t.card],['Total Massage Hours',(t.mins/60).toFixed(2)],['Total Staff Wages',t.wages],['Net After Wages',t.net],['Outstanding Staff Transfers',t.outTransfer],['Cash Balance / Other Outstanding',t.outCash],['Total Outstanding',t.outstanding],[],['SALES'],['Date','Branch','Customer','Type','Therapist','Therapist 2','Minutes','Room','Payment','Total','Shower','Deep Tissue']];S.sales.forEach(x=>rows.push([x.serviceDate,branches[x.branch]?.name,x.customer,x.type,x.therapist,x.therapist2||'',x.minutes,x.room||'',x.method,x.total,x.shower?'Yes':'No',x.deepTissue?'Yes':'No']));rows.push([],['STAFF PAYROLL BY DATE / BRANCH'],['Date','Branch','Staff','Massage Hours','Wage Due']);let payroll={};S.sales.forEach(x=>[x.therapist,x.therapist2].filter(Boolean).forEach(n=>{let k=[x.serviceDate,x.branch,n].join('|');payroll[k]=(payroll[k]||0)+(+x.minutes||0)}));Object.entries(payroll).forEach(([k,m])=>{let [d,b,n]=k.split('|');rows.push([d,branches[+b]?.name,n,(m/60).toFixed(2),m/60*35])});rows.push([],['OUTSTANDING STAFF PAYMENTS'],['Date','Branch','Staff','Method','Amount','Status']);S.carryovers.forEach(x=>rows.push([x.date,branches[x.branch]?.name,x.name,x.method||'Card',x.amount,x.paid?'Completed':'Outstanding']));rows.push([],['CASH BALANCE / OTHER OUTSTANDING'],['Date','Branch','Staff','Type','Amount','Status']);S.manualDebts.forEach(x=>rows.push([x.date,branches[x.branch]?.name,x.name,x.who==='store'?'Store owes staff':'Staff owes store',x.amount,x.paid?'Completed':'Outstanding']));downloadBlob('eternity-pos-business-export.csv',rows.map(r=>r.map(csvCell).join(',')).join('\n'),'text/csv;charset=utf-8')}
function downloadExcel(){let t=exportTotals(),sales=S.sales.map(x=>`<tr><td>${esc(x.serviceDate)}</td><td>${esc(branches[x.branch]?.name||'')}</td><td>${esc(x.customer)}</td><td>${esc(x.therapist)}</td><td>${x.minutes}</td><td>${esc(x.method)}</td><td>${x.total}</td></tr>`).join(''),payroll={};S.sales.forEach(x=>[x.therapist,x.therapist2].filter(Boolean).forEach(n=>{let k=[x.serviceDate,x.branch,n].join('|');payroll[k]=(payroll[k]||0)+(+x.minutes||0)}));let payRows=Object.entries(payroll).map(([k,m])=>{let [d,b,n]=k.split('|');return `<tr><td>${d}</td><td>${esc(branches[+b]?.name||'')}</td><td>${esc(n)}</td><td>${(m/60).toFixed(2)}</td><td>${(m/60*35).toFixed(2)}</td></tr>`}).join('');let html=`<html><body><h2>Eternity Massage POS - Business Export</h2><h3>Business Totals</h3><table border="1"><tr><th>Total Sales</th><th>Cash</th><th>Card</th><th>Hours</th><th>Staff Wages</th><th>Net After Wages</th><th>Total Outstanding</th></tr><tr><td>${t.sales}</td><td>${t.cash}</td><td>${t.card}</td><td>${(t.mins/60).toFixed(2)}</td><td>${t.wages.toFixed(2)}</td><td>${t.net.toFixed(2)}</td><td>${t.outstanding.toFixed(2)}</td></tr></table><h3>Sales</h3><table border="1"><tr><th>Date</th><th>Branch</th><th>Customer</th><th>Therapist</th><th>Minutes</th><th>Payment</th><th>Total</th></tr>${sales}</table><h3>Staff Payroll</h3><table border="1"><tr><th>Date</th><th>Branch</th><th>Staff</th><th>Hours</th><th>Wage Due</th></tr>${payRows}</table><h3>Outstanding Staff Payments</h3><table border="1"><tr><th>Date</th><th>Branch</th><th>Staff</th><th>Method</th><th>Amount</th><th>Status</th></tr>${S.carryovers.map(x=>`<tr><td>${x.date}</td><td>${esc(branches[x.branch]?.name||'')}</td><td>${esc(x.name)}</td><td>${esc(x.method||'Card')}</td><td>${x.amount}</td><td>${x.paid?'Completed':'Outstanding'}</td></tr>`).join('')}</table><h3>Cash Balance / Other Outstanding</h3><table border="1"><tr><th>Date</th><th>Branch</th><th>Staff</th><th>Type</th><th>Amount</th><th>Status</th></tr>${S.manualDebts.map(x=>`<tr><td>${x.date}</td><td>${esc(branches[x.branch]?.name||'')}</td><td>${esc(x.name)}</td><td>${x.who==='store'?'Store owes staff':'Staff owes store'}</td><td>${x.amount}</td><td>${x.paid?'Completed':'Outstanding'}</td></tr>`).join('')}</table></body></html>`;downloadBlob('eternity-pos-business-export.xls',html,'application/vnd.ms-excel')}
function sendDataEmail(){let e=document.querySelector('#dataEmail')?.value.trim();if(!e)return toast('Enter email');window.location.href='mailto:'+encodeURIComponent(e)+'?subject='+encodeURIComponent('Eternity Massage Summary')+'&body='+encodeURIComponent(summaryPlain('branches'))}
function dataCenterModal(){modal(`<button class="close" onclick="closeM()">×</button><div class="modal-title">${I('receipt')}<div><h2>Send & Export Data</h2><span>Send summary or export all business data</span></div></div><div class="field"><label>Mobile</label><input id="dataPhone" type="tel" inputmode="tel" placeholder="04xx xxx xxx"></div><div class="field"><label>Email</label><input id="dataEmail" type="email" placeholder="name@example.com"></div><div class="data-center-actions"><button type="button" class="primary" onclick="openSMS(document.querySelector('#dataPhone').value,summaryPlain('branches'))">${I('phone')} Send SMS</button><button type="button" class="primary" onclick="sendDataEmail()">${I('mail')} Send Email</button><button type="button" class="primary" onclick="downloadCsv()">Export All CSV</button><button type="button" class="primary" onclick="downloadExcel()">Export All Excel</button></div>`)}

function priceSettings(){let bi=S.branch,p=S.pricesByBranch[bi],rooms=S.roomsByBranch[bi]||[];modal(`<button class="close" onclick="closeM()">×</button><div class="modal-title">${I('edit')}<div><h2>Service Prices & Rooms</h2><span>${esc(branches[bi].name)} only · other branches are unchanged</span></div></div><div class="settings-subtitle">Service Prices</div>${p.map((s,i)=>`<div class="setting-row"><b>${s.m} minutes</b><input id="p${i}" type="number" value="${s.p}"></div>`).join('')}<div class="room-settings-head"><div><b>Available Treatment Rooms</b><small>Rename room numbers and switch rooms on/off for this branch.</small></div><button class="secondary-action" onclick="addRoomSetting(${bi})">${I('plus')} Add Room</button></div><div class="room-settings-list">${rooms.map((r,i)=>`<div class="room-setting-row"><div class="room-setting-icon">${I('home')}</div><div class="field"><label>Room</label><input id="roomnum${i}" type="number" min="1" value="${r.n}"></div><label class="room-enable"><span>${r.enabled?'Open':'Closed'}</span><span class="switch"><input id="roomen${i}" type="checkbox" ${r.enabled?'checked':''} onchange="this.closest('.room-enable').querySelector('span:first-child').textContent=this.checked?'Open':'Closed'"><i></i></span></label>${rooms.length>1?`<button class="room-remove" onclick="removeRoomSetting(${bi},${i})">×</button>`:''}</div>`).join('')}</div><button class="primary fullbtn" onclick="saveBranchPrices(${bi})">${I('check')} Save Prices & Rooms for This Store</button>`)}
function addRoomSetting(bi){let a=S.roomsByBranch[bi]||[],next=a.length?Math.max(...a.map(x=>+x.n||0))+1:1;a.push({n:next,enabled:true});S.roomsByBranch[bi]=a;save();closeM();priceSettings()}
function removeRoomSetting(bi,i){S.roomsByBranch[bi].splice(i,1);save();closeM();priceSettings()}

function saveBranchPrices(bi){S.pricesByBranch[bi].forEach((s,i)=>s.p=+document.querySelector('#p'+i).value||0);let seen=new Set(),ok=true;S.roomsByBranch[bi].forEach((r,i)=>{let n=+document.querySelector('#roomnum'+i).value||0;if(!n||seen.has(n)){ok=false;return}seen.add(n);r.n=n;r.enabled=!!document.querySelector('#roomen'+i).checked});if(!ok)return toast('Room numbers must be unique and greater than 0','danger');save();closeM();





render();speak('Store prices and rooms saved')}
function branchPinSettings(){modal(`<button class="close" onclick="closeM()">×</button><div class="modal-title">${I('lock')}<div><h2>Branch PINs</h2><span>Manage branch login, Reception and Boss access separately</span></div></div><div class="branch-pin-section"><div class="branch-pin-section-title"><b>Branch Login PINs</b><small>Used on each branch login screen</small></div>${branches.map((b,i)=>`<div class="setting-row branch-pin-row"><span><b>${esc(b.name)}</b><small>Branch login</small></span><input id="bp${i}" type="text" inputmode="numeric" pattern="[0-9]*" maxlength="4" value="${S.branchPins[i]}" class="visible-pin"></div>`).join('')}</div><div class="separate-access-pins"><div class="access-pin-card reception-access"><div class="access-pin-icon">${I('users')}</div><div class="access-pin-copy"><b>Reception PIN</b><small>Staff Availability only</small></div><div class="access-pin-input"><input id="receptionAccessPin" type="password" inputmode="numeric" pattern="[0-9]*" maxlength="4" value="${esc(S.receptionPin)}"><button type="button" onclick="toggleSettingsPin('receptionAccessPin',this)">${I('eye')}</button></div></div><div class="access-pin-card boss-access"><div class="access-pin-icon">${I('lock')}</div><div class="access-pin-copy"><b>Boss PIN</b><small>Reports + Settings only</small></div><div class="access-pin-input"><input id="bossAccessPin" type="password" inputmode="numeric" pattern="[0-9]*" maxlength="4" value="${esc(S.bossPin)}"><button type="button" onclick="toggleSettingsPin('bossAccessPin',this)">${I('eye')}</button></div></div></div><button class="primary fullbtn" onclick="savePins()">${I('check')} Save All PINs</button>`)}
function toggleSettingsPin(id,b){let e=document.getElementById(id);if(!e)return;e.type=e.type==='password'?'text':'password';if(b)b.innerHTML=I(e.type==='password'?'eye':'eye_off')}
function savePins(){for(let i=0;i<branches.length;i++){let e=document.querySelector('#bp'+i),v=e?.value||'';if(!/^\d{4}$/.test(v))return toast('Every branch PIN must be 4 digits','danger');S.branchPins[i]=v}let r=document.querySelector('#receptionAccessPin')?.value||'',b=document.querySelector('#bossAccessPin')?.value||'';if(!/^\d{4}$/.test(r))return toast('Reception PIN must be 4 digits','danger');if(!/^\d{4}$/.test(b))return toast('Boss PIN must be 4 digits','danger');S.receptionPin=r;S.bossPin=b;window.receptionUnlockedBranch=null;window.bossUnlockedBranch=null;save();closeM();speak('PIN settings saved');toast('All PINs saved','success')}
function taxSettings(){modal(`<button class="close" onclick="closeM()">×</button><div class="modal-title">${I('percent')}<div><h2>Tax & E-Receipt</h2><span>Optional settings for this POS</span></div></div><label class="toggleline"><span><b>Enable Tax</b><small>Calculate tax component in reports and receipts</small></span><input id="taxOn" type="checkbox" ${S.tax.enabled?'checked':''}></label><div class="field"><label>Tax Rate (%)</label><input id="taxRate" type="number" min="0" step=".1" value="${S.tax.rate}"></div><label class="toggleline"><span><b>Offer E-Receipt</b><small>Show e-receipt option after payment</small></span><input id="erec" type="checkbox" ${S.tax.eReceipt?'checked':''}></label><button class="primary fullbtn" onclick="S.tax={enabled:taxOn.checked,rate:+taxRate.value||0,eReceipt:erec.checked};save();closeM();speak('Tax settings saved')">${I('check')} Save Tax Settings</button>`)}
function showBookingNotice(title,msg){let old=document.querySelector('.booking-float-notice');if(old)old.remove();let n=document.createElement('div');n.className='booking-float-notice';n.innerHTML=`${I('bell')}<div><b>${esc(title)}</b><span>${esc(msg)}</span></div><button onclick="this.parentElement.remove()">×</button>`;document.body.appendChild(n);setTimeout(()=>n.remove(),7000)}
function checkAlerts(){let n=Date.now(),changed=false;S.bookings.forEach(b=>{if(b.branch!==S.branch||b.paid||b.status==='Cancelled')return;let d=+new Date(`${b.date}T${b.time}`)-n,mins=Math.ceil(d/60000);if(d>0&&d<=10*60000&&!b.alerted10){b.alerted10=true;changed=true;speak(`Booking reminder. ${b.name||'Customer'} arrives in 10 minutes.`);tone(650,.18);toast(`Booking in 10 min: ${b.name} · ${b.phone||'No phone'}`,'alert');showBookingNotice('Booking in 10 minutes',`${b.name||'Customer'} · ${b.time} · ${b.phone||'No phone'}`)}if(d>0&&d<=5*60000&&!b.alerted5){b.alerted5=true;changed=true;speak(`Booking reminder. ${b.name||'Customer'} arrives in 5 minutes. Please prepare.`);tone(760,.22);toast(`Booking in 5 min: ${b.name} · ${b.phone||'No phone'}`,'alert');showBookingNotice('Booking in 5 minutes',`${b.name||'Customer'} · ${b.time} · ${b.phone||'No phone'}`)}});if(changed)save()}
setInterval(()=>{checkAlerts();if(['customers','staff','availability','bookings','reports'].includes(S.page)&&document.querySelector('.app'))render()},5000);
login();
